COURSE.add({
  id: 'm14', order: 14, icon: '🧩',
  title: { en: 'The rest of the AWS AI family, and certifications', he: 'שאר משפחת ה-AI של AWS, והסמכות' },
  summary: { en: 'SageMaker AI, Kiro, AWS Quick, Nova, the classic AI services, which names are retired, and the exams that prove what you know.', he: 'SageMaker AI, Kiro, AWS Quick, Nova, שירותי ה-AI הקלאסיים, אילו שמות יצאו לפנסיה, והמבחנים שמוכיחים מה אתה יודע.' },
  glossary: [
    { term: 'SageMaker AI', aka: ['Amazon SageMaker AI'], en: 'The AWS service for building, training and hosting your own ML models and open foundation models. It is the old "Amazon SageMaker", renamed.', he: 'שירות AWS לבנייה, אימון ואירוח של מודלי ML משלך ושל foundation models פתוחים. זה "Amazon SageMaker" הישן, בשם חדש.' },
    { term: 'JumpStart', aka: ['SageMaker JumpStart'], en: 'The model hub inside SageMaker AI: 150+ ready public models that you can deploy or fine-tune with a few clicks.', he: 'מאגר המודלים בתוך SageMaker AI: יותר מ-150 מודלים ציבוריים מוכנים שאפשר לפרוס או לעשות להם fine-tuning בכמה לחיצות.' },
    { term: 'Endpoint', aka: ['real-time endpoint', 'endpoints'], en: 'In SageMaker AI: a model running on compute that you pay for, waiting for requests. You call it with InvokeEndpoint.', he: 'ב-SageMaker AI: מודל שרץ על מחשוב שאתה משלם עליו ומחכה לבקשות. קוראים לו עם InvokeEndpoint.' },
    { term: 'Training job', aka: ['training jobs'], en: 'A managed run that trains or fine-tunes a model on your data, on machines that exist only for that run.', he: 'ריצה מנוהלת שמאמנת מודל או עושה לו fine-tuning על המידע שלך, על מכונות שקיימות רק לריצה הזו.' },
    { term: 'Model Registry', en: 'The SageMaker AI catalog where model versions are stored and approved before they go to production.', he: 'הקטלוג של SageMaker AI שבו שומרים גרסאות של מודלים ומאשרים אותן לפני שהן עולות לפרודקשן.' },
    { term: 'SageMaker Unified Studio', aka: ['Unified Studio'], en: 'The browser workspace of the next-generation Amazon SageMaker: one project-based place for data, analytics, SageMaker AI and Bedrock.', he: 'סביבת העבודה בדפדפן של Amazon SageMaker מהדור הבא: מקום אחד, מבוסס פרויקטים, לדאטה, אנליטיקה, SageMaker AI ו-Bedrock.' },
    { term: 'Custom Model Import', en: 'A Bedrock feature: bring your own open-weight model files and serve them through Bedrock.', he: 'יכולת של Bedrock: מביאים קבצי מודל פתוח משלך ומגישים אותו דרך Bedrock.' },
    { term: 'Maintenance', aka: ['maintenance mode'], en: 'AWS lifecycle word: the service is closed to new customers, existing customers keep working, and no new features are added.', he: 'מונח מחזור-חיים של AWS: השירות סגור ללקוחות חדשים, לקוחות קיימים ממשיכים לעבוד, ולא מוסיפים יכולות חדשות.' },
    { term: 'Sunset', en: 'AWS lifecycle word: an end-of-support date has been set. After that date the service or feature stops.', he: 'מונח מחזור-חיים של AWS: נקבע תאריך סיום תמיכה. אחרי התאריך הזה השירות או היכולת מפסיקים.' },
    { term: 'EOL', aka: ['End of life', 'Legacy'], en: 'End of life. For a Bedrock model: first it becomes Legacy (still works, plan to move), then EOL (calls fail).', he: 'End of life. במודל של Bedrock: קודם הוא הופך ל-Legacy (עדיין עובד, צריך לתכנן מעבר), ואז EOL (קריאות נכשלות).' },
    { term: 'Kiro', en: 'The AWS agentic development environment (IDE, CLI and web app). It is the official successor to Amazon Q Developer.', he: 'סביבת הפיתוח האגנטית של AWS (IDE, CLI ואפליקציית web). היורש הרשמי של Amazon Q Developer.' },
    { term: 'Spec', aka: ['specs', 'spec-driven development'], en: 'In Kiro: a written plan (requirements, then design, then tasks) that the agent follows instead of jumping straight to code.', he: 'ב-Kiro: תוכנית כתובה (דרישות, אחר כך תכנון, אחר כך משימות) שהסוכן עובד לפיה במקום לקפוץ ישר לקוד.' },
    { term: 'Steering', aka: ['steering files'], en: 'In Kiro: files with permanent project rules that the agent reads in every task.', he: 'ב-Kiro: קבצים עם כללי פרויקט קבועים שהסוכן קורא בכל משימה.' },
    { term: 'Amazon Q Developer', aka: ['Q Developer'], en: 'The older AWS coding assistant (it replaced CodeWhisperer). Its IDE plugins and paid plans end on 2027-04-30; Kiro replaces it.', he: 'עוזר הקוד הישן יותר של AWS (החליף את CodeWhisperer). התוספים ל-IDE והתוכניות בתשלום מסתיימים ב-2027-04-30; Kiro מחליף אותו.' },
    { term: 'Amazon Q Business', aka: ['Q Business'], en: 'A managed company assistant that answers from company data. In maintenance since mid-2026; AWS points customers to AWS Quick.', he: 'עוזר ארגוני מנוהל שעונה מתוך מידע של החברה. ב-maintenance מאמצע 2026; AWS מפנה לקוחות ל-AWS Quick.' },
    { term: 'AWS Quick', aka: ['Amazon Quick', 'Quick Suite', 'QuickSight'], en: 'The AWS AI workspace for business users: chat agents, research, automation and BI. Earlier names: QuickSight, Quick Suite, Amazon Quick.', he: 'סביבת ה-AI של AWS למשתמשים עסקיים: סוכני צ׳אט, מחקר, אוטומציה ו-BI. שמות קודמים: QuickSight, Quick Suite, Amazon Quick.' },
    { term: 'AWS Transform', en: 'An agentic service that modernizes old code and systems (.NET, VMware, mainframe). It took over the code-upgrade features of Q Developer.', he: 'שירות אגנטי שמחדש קוד ומערכות ישנים (.NET, VMware, mainframe). קיבל את יכולות שדרוג הקוד של Q Developer.' },
    { term: 'Amazon Nova', aka: ['Nova'], en: 'Amazon\'s own model family on Bedrock: text and multimodal models, speech-to-speech (Sonic) and embeddings.', he: 'משפחת המודלים של Amazon עצמה ב-Bedrock: מודלי טקסט ומולטימודל, דיבור-לדיבור (Sonic) ו-embeddings.' },
    { term: 'Nova Act', en: 'An AWS service and SDK for agents that operate a web browser to automate work in web interfaces.', he: 'שירות ו-SDK של AWS לסוכנים שמפעילים דפדפן כדי לבצע אוטומציה של עבודה בממשקי web.' },
    { term: 'Titan', aka: ['Amazon Titan'], en: 'Amazon\'s older model family. In Bedrock today only the embeddings models remain, mainly Titan Text Embeddings V2.', he: 'משפחת המודלים הישנה יותר של Amazon. היום ב-Bedrock נשארו רק מודלי ה-embeddings, בעיקר Titan Text Embeddings V2.' },
    { term: 'Bedrock Data Automation', aka: ['BDA'], en: 'A Bedrock service that turns documents, images, audio and video into structured output through one API.', he: 'שירות של Bedrock שהופך מסמכים, תמונות, אודיו ווידאו לפלט מובנה דרך API אחד.' },
    { term: 'Blueprint', aka: ['blueprints'], en: 'In BDA: a schema that lists the fields you want pulled out of a document (for example invoice number and total).', he: 'ב-BDA: סכמה שמפרטת את השדות שרוצים לחלץ ממסמך (לדוגמה מספר חשבונית וסכום).' },
    { term: 'S3 Vectors', aka: ['Amazon S3 Vectors', 'vector bucket'], en: 'Vector storage and similarity search built into Amazon S3. A cheap vector store for RAG and agent memory.', he: 'אחסון וקטורים וחיפוש דמיון שבנויים בתוך Amazon S3. vector store זול ל-RAG ולזיכרון של סוכנים.' },
    { term: 'PartyRock', en: 'A free no-code website (partyrock.aws) for building small GenAI apps on Bedrock models. Good for learning and demos.', he: 'אתר חינמי בלי קוד (partyrock.aws) לבניית אפליקציות GenAI קטנות על מודלים של Bedrock. טוב ללמידה ולדמואים.' },
    { term: 'OCR', en: 'Optical Character Recognition: reading the text that appears in an image or a scanned page.', he: 'Optical Character Recognition: קריאת הטקסט שמופיע בתמונה או בדף סרוק.' },
    { term: 'Classic AI services', aka: ['Comprehend', 'Textract', 'Transcribe', 'Polly', 'Rekognition', 'Translate', 'Lex', 'Personalize'], en: 'Single-purpose AWS AI APIs that existed before GenAI: Comprehend (text analysis), Textract (documents), Transcribe (speech to text), Polly (text to speech), Rekognition (images), Translate, Lex (bots), Personalize.', he: 'APIs של AWS למטרה אחת, שהיו קיימים לפני GenAI: Comprehend (ניתוח טקסט), Textract (מסמכים), Transcribe (דיבור לטקסט), Polly (טקסט לדיבור), Rekognition (תמונות), Translate, Lex (בוטים), Personalize.' },
    { term: 'Kendra', aka: ['Amazon Kendra'], en: 'The older AWS enterprise search service. In maintenance since mid-2026; AWS says to use a Bedrock Managed Knowledge Base instead.', he: 'שירות החיפוש הארגוני הישן של AWS. ב-maintenance מאמצע 2026; AWS אומרת להשתמש במקומו ב-Bedrock Managed Knowledge Base.' },
    { term: 'AIF-C01', aka: ['AI Practitioner'], en: 'AWS Certified AI Practitioner. The entry-level (Foundational) AI exam.', he: 'AWS Certified AI Practitioner. מבחן ה-AI ברמת הכניסה (Foundational).' },
    { term: 'AIP-C01', aka: ['Generative AI Developer - Professional'], en: 'AWS Certified Generative AI Developer - Professional. The exam that fits this course best.', he: 'AWS Certified Generative AI Developer - Professional. המבחן שהכי מתאים לקורס הזה.' },
    { term: 'MLA-C02', aka: ['MLA-C01', 'ML Engineer Associate'], en: 'AWS Certified Machine Learning Engineer - Associate. C02 is the new version (beta since 2026-09-29) with much more GenAI.', he: 'AWS Certified Machine Learning Engineer - Associate. C02 היא הגרסה החדשה (בטא מ-2026-09-29) עם הרבה יותר GenAI.' },
    { term: 'What\'s New', aka: ['Whats New'], en: 'The official AWS news feed (aws.amazon.com/about-aws/whats-new). Every launch and every change of status is posted there.', he: 'פיד החדשות הרשמי של AWS (aws.amazon.com/about-aws/whats-new). כל השקה וכל שינוי סטטוס מתפרסמים שם.' }
  ],
  lessons: [
    {
      id: 'm14l1', minutes: 13,
      title: { en: 'Amazon SageMaker AI: when you own the model', he: 'Amazon SageMaker AI: כשהמודל שלך' },
      blocks: [
        { t: 'p', en: 'Until now you **rented** models: you sent tokens to [[Bedrock]] and paid per token. Sometimes that is not enough. You have your own model, or you need a model that Bedrock does not offer, or you want full control over the machine it runs on. That is the job of [[SageMaker AI]].', he: 'עד עכשיו **שכרת** מודלים: שלחת טוקנים ל-[[Bedrock]] ושילמת לפי טוקן. לפעמים זה לא מספיק. יש לך מודל משלך, או שאתה צריך מודל ש-Bedrock לא מציע, או שאתה רוצה שליטה מלאה במכונה שהוא רץ עליה. זו העבודה של [[SageMaker AI]].' },
        { t: 'note', kind: 'jargon', en: 'Two names that sound the same. **Amazon SageMaker AI** = the ML service (train, fine-tune, host). It is the old "Amazon SageMaker", renamed at the end of 2024. **Amazon SageMaker** (next generation) = the wider data + analytics + AI platform. Its browser workspace is [[SageMaker Unified Studio]]. In old blogs "SageMaker" almost always means what is now SageMaker AI.', he: 'שני שמות שנשמעים אותו דבר. **Amazon SageMaker AI** = שירות ה-ML (אימון, fine-tuning, אירוח). זה "Amazon SageMaker" הישן, ששמו שונה בסוף 2024. **Amazon SageMaker** (הדור הבא) = הפלטפורמה הרחבה של דאטה + אנליטיקה + AI. סביבת העבודה שלה בדפדפן היא [[SageMaker Unified Studio]]. בבלוגים ישנים "SageMaker" כמעט תמיד מתכוון למה שהיום נקרא SageMaker AI.' },
        { t: 'h', en: 'The parts you should know by name', he: 'החלקים שכדאי להכיר בשם' },
        { t: 'table', head: { en: ['Part', 'What it does'], he: ['חלק', 'מה הוא עושה'] }, rows: {
          en: [['[[JumpStart]]', '150+ pretrained public models (and paid models through AWS Marketplace). Deploy one as is, or fine-tune it.'], ['[[Training job]]', 'Runs your training or fine-tuning code on machines that live only for the job.'], ['Pipelines', 'Automates the ML workflow: prepare data, train, evaluate, register. No extra charge for the feature itself.'], ['[[Model Registry]]', 'Versions of models, with an approval step before production.'], ['[[Endpoint]]', 'The trained model, running and waiting for requests.']],
          he: [['[[JumpStart]]', 'יותר מ-150 מודלים ציבוריים מאומנים מראש (ומודלים בתשלום דרך AWS Marketplace). פורסים כמו שהוא, או עושים fine-tuning.'], ['[[Training job]]', 'מריץ את קוד האימון או ה-fine-tuning שלך על מכונות שחיות רק בזמן הריצה.'], ['Pipelines', 'אוטומציה של תהליך ה-ML: הכנת דאטה, אימון, הערכה, רישום. אין תשלום נוסף על היכולת עצמה.'], ['[[Model Registry]]', 'גרסאות של מודלים, עם שלב אישור לפני פרודקשן.'], ['[[Endpoint]]', 'המודל המאומן, רץ ומחכה לבקשות.']] } },
        { t: 'h', en: 'Four ways to serve a model', he: 'ארבע דרכים להגיש מודל' },
        { t: 'p', en: 'In Bedrock, [[Inference]] is one API call and AWS runs the machines. In SageMaker AI **you choose how the model is hosted**, and that choice decides cost and latency.', he: 'ב-Bedrock, [[Inference]] הוא קריאת API אחת ו-AWS מריצה את המכונות. ב-SageMaker AI **אתה בוחר איך המודל מתארח**, והבחירה הזו קובעת עלות ו-latency.' },
        { t: 'table', head: { en: ['Option', 'Limits', 'Good for'], he: ['אפשרות', 'גבולות', 'טוב בשביל'] }, rows: {
          en: [['Real-time endpoint', 'Payload up to 6 MB, answer within 60 s', 'Interactive apps. The machine runs (and bills) all the time.'], ['Serverless', 'Pay per millisecond of compute', 'Traffic that comes in bursts with quiet hours between.'], ['Asynchronous', 'Payload up to 1 GB, up to 15 minutes, can scale to zero', 'Big inputs and slow jobs where the caller can wait.'], ['Batch transform', 'A whole dataset in, a whole dataset out', 'Offline scoring of many records at once.']],
          he: [['Real-time endpoint', 'Payload עד 6 MB, תשובה בתוך 60 שניות', 'אפליקציות אינטראקטיביות. המכונה רצה (ומחויבת) כל הזמן.'], ['Serverless', 'משלמים לפי מילישנייה של מחשוב', 'תעבורה שמגיעה בגלים עם שעות שקטות ביניהם.'], ['Asynchronous', 'Payload עד 1 GB, עד 15 דקות, יכול לרדת לאפס', 'קלטים גדולים ועבודות איטיות שבהן הקורא יכול לחכות.'], ['Batch transform', 'דאטהסט שלם נכנס, דאטהסט שלם יוצא', 'ניקוד אופליין של הרבה רשומות בבת אחת.']] } },
        { t: 'note', kind: 'warn', en: 'The classic expensive mistake: someone deploys a JumpStart model to a real-time [[Endpoint]] "just to try", and forgets it. An endpoint bills for the machine **every hour, with zero requests**. Bedrock on-demand bills only when you send tokens. After every experiment: delete the endpoint.', he: 'הטעות היקרה הקלאסית: מישהו פורס מודל מ-JumpStart ל-[[Endpoint]] מסוג real-time "רק לנסות", ושוכח אותו. endpoint מחייב על המכונה **כל שעה, גם עם אפס בקשות**. Bedrock on-demand מחייב רק כששולחים טוקנים. אחרי כל ניסוי: מוחקים את ה-endpoint.' },
        { t: 'quiz', q: { en: 'A legal-tech team must process contracts that are 300 MB scanned files. One file takes about 8 minutes on their own model. Which SageMaker AI inference option fits?', he: 'צוות legal-tech צריך לעבד חוזים שהם קבצים סרוקים של 300 MB. קובץ אחד לוקח בערך 8 דקות במודל שלהם. איזו אפשרות inference של SageMaker AI מתאימה?' },
          options: { en: ['Real-time endpoint', 'Asynchronous inference', 'Serverless inference with a longer timeout', 'A real-time endpoint behind a load balancer'], he: ['Real-time endpoint', 'Asynchronous inference', 'Serverless inference עם timeout ארוך יותר', 'Real-time endpoint מאחורי load balancer'] },
          answer: 1, explain: { en: 'Asynchronous inference accepts payloads up to 1 GB and runs up to 15 minutes, and it can scale to zero between jobs. A real-time endpoint stops at 6 MB and 60 seconds, so no load balancer will save it.', he: 'Asynchronous inference מקבל payload עד 1 GB ורץ עד 15 דקות, ויכול לרדת לאפס בין עבודות. Real-time endpoint נעצר ב-6 MB וב-60 שניות, אז שום load balancer לא יציל אותו.' } },
        { t: 'h', en: 'Calling an endpoint from code', he: 'קריאה ל-endpoint מקוד' },
        { t: 'p', en: 'There are two boto3 clients, the same split you know from Bedrock: `sagemaker` creates and manages things (control plane), and `sagemaker-runtime` sends requests to a running endpoint with `InvokeEndpoint`.', he: 'יש שני boto3 clients, אותה חלוקה שאתה מכיר מ-Bedrock: `sagemaker` יוצר ומנהל דברים (control plane), ו-`sagemaker-runtime` שולח בקשות ל-endpoint רץ עם `InvokeEndpoint`.' },
        { t: 'fill', prompt: { en: 'Your team hosts an open model on a SageMaker AI endpoint. Complete the client name and the call. (The exact request parameters are in the API reference; they are hidden here.)', he: 'הצוות שלך מארח מודל פתוח על endpoint של SageMaker AI. השלם את שם ה-client ואת הקריאה. (הפרמטרים המדויקים של הבקשה נמצאים ב-API reference; כאן הם מוסתרים.)' },
          lang: 'python', code: 'import boto3\n\nsmr = boto3.client("{{1}}")\nresponse = smr.{{2}}(...)   # endpoint name, content type, body', blanks: [ { accept: ['sagemaker-runtime'], hint: { en: 'the data-plane client, not the control-plane one', he: 'ה-client של ה-data plane, לא של ה-control plane' } }, { accept: ['invoke_endpoint'], hint: { en: 'snake_case of InvokeEndpoint', he: 'snake_case של InvokeEndpoint' } } ],
          explain: { en: '`sagemaker` builds, `sagemaker-runtime` invokes. The request body is whatever format the model container expects, so there is no single message format like Converse. That is part of the price of owning the model.', he: '`sagemaker` בונה, `sagemaker-runtime` מפעיל. גוף הבקשה הוא בפורמט שה-container של המודל מצפה לו, אז אין פורמט הודעות אחיד כמו ב-Converse. זה חלק מהמחיר של בעלות על המודל.' } },
        { t: 'h', en: 'Bedrock or SageMaker AI?', he: 'Bedrock או SageMaker AI?' },
        { t: 'table', head: { en: ['Question', 'Bedrock', 'SageMaker AI'], he: ['שאלה', 'Bedrock', 'SageMaker AI'] }, rows: {
          en: [['What do you get?', 'An API to models that AWS runs', 'Machines and tools to run **your** model'], ['What do you pay for?', 'Tokens (on-demand), or reserved capacity', 'Compute, storage and data processing that you use'], ['Who patches and scales?', 'AWS', 'AWS runs the service, you choose instance type, count and scaling'], ['Which models?', 'The Bedrock catalog (Claude, Nova, GPT, Llama…)', 'Anything: your own, open models from JumpStart, a custom container'], ['Fine-tuning', 'A few models, simple, managed', 'Any model, full control of the training code'], ['Typical user', 'App developer', 'ML engineer / data scientist']],
          he: [['מה מקבלים?', 'API למודלים ש-AWS מריצה', 'מכונות וכלים להרצת המודל **שלך**'], ['על מה משלמים?', 'טוקנים (on-demand), או קיבולת שמורה', 'מחשוב, אחסון ועיבוד דאטה שהשתמשת בהם'], ['מי מעדכן ועושה scaling?', 'AWS', 'AWS מריצה את השירות, אתה בוחר סוג מכונה, כמות ו-scaling'], ['אילו מודלים?', 'הקטלוג של Bedrock (Claude, Nova, GPT, Llama…)', 'כל דבר: שלך, מודלים פתוחים מ-JumpStart, container משלך'], ['Fine-tuning', 'כמה מודלים, פשוט, מנוהל', 'כל מודל, שליטה מלאה בקוד האימון'], ['משתמש טיפוסי', 'מפתח אפליקציות', 'ML engineer / data scientist']] } },
        { t: 'note', kind: 'tip', en: 'The two are not enemies. Three bridges exist: (1) [[Custom Model Import]] brings your own open-weight model files (from S3 or SageMaker AI) into Bedrock, so your app keeps using Bedrock APIs. (2) **Bedrock Marketplace** deploys extra catalog models to an endpoint managed by SageMaker AI, and you still call them through Converse or InvokeModel. (3) "Amazon Bedrock in SageMaker Unified Studio" is a governed playground and app builder for teams that work with SSO and projects instead of the AWS console.', he: 'השניים לא אויבים. יש שלושה גשרים: (1) [[Custom Model Import]] מביא קבצי מודל פתוח משלך (מ-S3 או מ-SageMaker AI) לתוך Bedrock, כך שהאפליקציה ממשיכה להשתמש ב-APIs של Bedrock. (2) **Bedrock Marketplace** פורס מודלים נוספים מהקטלוג ל-endpoint שמנוהל על ידי SageMaker AI, ועדיין קוראים להם דרך Converse או InvokeModel. (3) "Amazon Bedrock in SageMaker Unified Studio" הוא playground ובונה אפליקציות מנוהל, לצוותים שעובדים עם SSO ופרויקטים במקום ה-console של AWS.' },
        { t: 'console', service: 'Amazon Bedrock', nav: ['#Tune', 'Custom models', 'Imported models', '#Infer', 'Custom model on-demand', 'Provisioned Throughput', 'Batch inference'], active: 'Custom models',
          crumbs: ['Amazon Bedrock', 'Custom models', 'Deploy for on-demand'],
          heading: 'Deploy for on-demand',
          panels: [ { title: 'Deployment details', n: 1, fields: [ { label: 'Deployment Name', type: 'input', value: 'support-tone-nova-lite', n: 2 }, { label: 'Description', type: 'input', value: 'Nova Lite fine-tuned on our support answers' }, { label: 'Tags', type: 'text', value: 'team = support' } ] } ],
          buttons: ['Cancel', 'Create'],
          callouts: [ { n: 1, en: 'You reach this screen from **Custom models** (under **Tune**) → **Models** tab → select the model → **Set up inference** → **Deploy for on-demand**.', he: 'מגיעים למסך הזה מ-**Custom models** (תחת **Tune**) ← לשונית **Models** ← בוחרים מודל ← **Set up inference** ← **Deploy for on-demand**.' }, { n: 2, en: 'When the deployment is Active, its ARN is used as `modelId` in Converse. You pay per token, with no machine to forget. This is the fine-tuning path that needs no SageMaker AI at all.', he: 'כשה-deployment במצב Active, ה-ARN שלו משמש כ-`modelId` ב-Converse. משלמים לפי טוקן, בלי מכונה שאפשר לשכוח. זה מסלול ה-fine-tuning שלא צריך SageMaker AI בכלל.' } ],
          caption: { en: 'Simplified. Fine-tuning inside Bedrock: for a few supported base models (for example Nova Lite, Nova 2 Lite, Nova Micro, Nova Pro, Llama 3.3 70B, in specific Regions) the tuned model can be served on demand.', he: 'מפושט. Fine-tuning בתוך Bedrock: לכמה מודלי בסיס נתמכים (לדוגמה Nova Lite, Nova 2 Lite, Nova Micro, Nova Pro, Llama 3.3 70B, ב-Regions מסוימים) אפשר להגיש את המודל המכוונן on demand.' } },
        { t: 'match', prompt: { en: 'Match each need to the best home for it.', he: 'התאם כל צורך לבית הכי טוב בשבילו.' }, pairs: [
          { a: { en: 'A chatbot on Claude with RAG, shipped next month', he: 'צ׳אטבוט על Claude עם RAG, שעולה בחודש הבא' }, b: { en: 'Bedrock on-demand', he: 'Bedrock on-demand' } },
          { a: { en: 'A fraud model that data scientists train on tables every week', he: 'מודל הונאות ש-data scientists מאמנים על טבלאות כל שבוע' }, b: { en: 'SageMaker AI training jobs + Pipelines', he: 'SageMaker AI training jobs + Pipelines' } },
          { a: { en: 'Your own fine-tuned Llama weights, but the app must keep calling InvokeModel', he: 'משקלות Llama שעשית להם fine-tuning, אבל האפליקציה חייבת להמשיך לקרוא ל-InvokeModel' }, b: { en: 'Bedrock Custom Model Import', he: 'Bedrock Custom Model Import' } },
          { a: { en: 'An open model that needs a special GPU and a custom container', he: 'מודל פתוח שצריך GPU מיוחד ו-container משלו' }, b: { en: 'SageMaker AI endpoint', he: 'SageMaker AI endpoint' } },
          { a: { en: 'Analysts with SSO and no console access want a governed GenAI playground', he: 'אנליסטים עם SSO ובלי גישה ל-console רוצים playground מנוהל ל-GenAI' }, b: { en: 'Amazon Bedrock in SageMaker Unified Studio', he: 'Amazon Bedrock in SageMaker Unified Studio' } }
        ] },
        { t: 'note', kind: 'info', en: 'Status check, November 2026: SageMaker AI itself is active. But several of its side features went into [[Maintenance]] on 2026-06-30 (closed to new customers from 2026-07-30): Clarify, Model Monitor, Ground Truth, Augmented AI (A2I), Debugger, Role Manager, GeoSpatial and Studio Lab. Ground Truth Plus is shut down. Odd but true: Clarify, Model Monitor and Ground Truth are still on the in-scope list of the AIP-C01 exam, so know what they were for.', he: 'בדיקת סטטוס, נובמבר 2026: SageMaker AI עצמו פעיל. אבל כמה יכולות צד שלו עברו ל-[[Maintenance]] ב-2026-06-30 (סגורות ללקוחות חדשים מ-2026-07-30): Clarify, Model Monitor, Ground Truth, Augmented AI (A2I), Debugger, Role Manager, GeoSpatial ו-Studio Lab. Ground Truth Plus נסגר. מוזר אבל נכון: Clarify, Model Monitor ו-Ground Truth עדיין ברשימת השירותים של מבחן AIP-C01, אז כדאי לדעת למה הם שימשו.' },
        { t: 'quiz', q: { en: 'A startup serves 200 requests per day to a 7B open model on a GPU real-time endpoint. The bill is high. The model architecture is one that Bedrock Custom Model Import supports. What is the most sensible first move?', he: 'סטארטאפ מגיש 200 בקשות ביום למודל פתוח של 7B על real-time endpoint עם GPU. החשבון גבוה. הארכיטקטורה של המודל נתמכת ב-Bedrock Custom Model Import. מה הצעד הראשון הכי הגיוני?' },
          options: { en: ['Buy a bigger instance so each request finishes faster', 'Add a second endpoint in another Region', 'Stop paying for an always-on machine: move to an option that bills by use, such as Custom Model Import or async/serverless hosting', 'Fine-tune the model again with more data'], he: ['לקנות מכונה גדולה יותר כדי שכל בקשה תסתיים מהר יותר', 'להוסיף endpoint שני ב-Region אחר', 'להפסיק לשלם על מכונה שתמיד דולקת: לעבור לאפשרות שמחייבת לפי שימוש, כמו Custom Model Import או אירוח async/serverless', 'לעשות fine-tuning נוסף עם יותר דאטה'] },
          answer: 2, explain: { en: 'At 200 requests per day the machine is idle almost all the time, and a real-time endpoint bills for idle hours. Imported models in Bedrock are billed in Custom Model Units per minute while copies are active, and SageMaker async can scale to zero. A bigger instance only makes the idle hours more expensive.', he: 'ב-200 בקשות ביום המכונה כמעט תמיד במנוחה, ו-real-time endpoint מחייב גם על שעות מנוחה. מודלים מיובאים ב-Bedrock מחויבים ב-Custom Model Units לדקה כשעותקים פעילים, ו-async של SageMaker יכול לרדת לאפס. מכונה גדולה יותר רק מייקרת את שעות המנוחה.' } },
        { t: 'reveal', q: { en: 'Interview: "We already use Bedrock. Give me two honest reasons to add SageMaker AI, and one reason not to."', he: 'ראיון: "אנחנו כבר משתמשים ב-Bedrock. תן לי שתי סיבות כנות להוסיף SageMaker AI, וסיבה אחת לא להוסיף."' },
          a: { en: 'Reasons to add: (1) we need a model Bedrock does not serve, or our own trained model, with a specific instance type or container. (2) we do classic ML (tables, forecasts, ranking) that an LLM is the wrong tool for, and we need training jobs, Pipelines and a Model Registry. Reason not to: operations. With endpoints we own capacity planning, scaling and idle cost, and we lose the single Converse format, guardrails in the same call and per-token billing. If a Bedrock model with a good prompt or RAG solves the task, that is cheaper to run.', he: 'סיבות להוסיף: (1) צריך מודל ש-Bedrock לא מגיש, או מודל שאימנו בעצמנו, עם סוג מכונה או container מסוים. (2) עושים ML קלאסי (טבלאות, תחזיות, דירוג) ש-LLM הוא הכלי הלא נכון בשבילו, וצריך training jobs, Pipelines ו-Model Registry. סיבה לא להוסיף: תפעול. עם endpoints אנחנו אחראים על תכנון קיבולת, scaling ועלות מנוחה, ומאבדים את פורמט Converse האחיד, guardrails באותה קריאה וחיוב לפי טוקן. אם מודל של Bedrock עם פרומפט טוב או RAG פותר את המשימה, זה זול יותר להפעלה.' } }
      ]
    },
    {
      id: 'm14l2', minutes: 13,
      title: { en: 'Assistants and developer tools: what is current, what is retiring', he: 'עוזרים וכלי פיתוח: מה עדכני ומה יוצא לפנסיה' },
      blocks: [
        { t: 'p', en: 'This lesson is a map of names. AWS renamed and retired many AI products in 2025 and 2026. Blogs, videos and even some exam guides still use the old names. A pro knows both the old name and what replaced it.', he: 'השיעור הזה הוא מפה של שמות. AWS שינתה שמות והוציאה לפנסיה הרבה מוצרי AI ב-2025 וב-2026. בלוגים, סרטונים ואפילו חלק ממדריכי המבחנים עדיין משתמשים בשמות הישנים. מקצוען מכיר גם את השם הישן וגם את מה שהחליף אותו.' },
        { t: 'h', en: 'First, three lifecycle words', he: 'קודם כול, שלוש מילות מחזור-חיים' },
        { t: 'table', head: { en: ['Word', 'What it means for you'], he: ['מילה', 'מה זה אומר בשבילך'] }, rows: {
          en: [['[[Maintenance]]', 'Closed to **new** customers. Existing customers keep working. Only bug and security fixes. No end date yet.'], ['[[Sunset]]', 'An end-of-support date is announced. Plan the migration before that date.'], ['Shut down', 'Gone. Calls fail.'], ['Legacy → [[EOL]] (Bedrock models)', 'A model version is first marked Legacy, later EOL. After EOL the call fails with an error.']],
          he: [['[[Maintenance]]', 'סגור ללקוחות **חדשים**. לקוחות קיימים ממשיכים לעבוד. רק תיקוני באגים ואבטחה. עדיין אין תאריך סיום.'], ['[[Sunset]]', 'הוכרז תאריך סיום תמיכה. מתכננים מעבר לפני התאריך.'], ['Shut down', 'נעלם. קריאות נכשלות.'], ['Legacy ← [[EOL]] (מודלים ב-Bedrock)', 'גרסת מודל מסומנת קודם Legacy, ואחר כך EOL. אחרי EOL הקריאה נכשלת עם שגיאה.']] } },
        { t: 'h', en: 'Coding assistants: Amazon Q Developer → Kiro', he: 'עוזרי קוד: Amazon Q Developer ← Kiro' },
        { t: 'p', en: '[[Kiro]] is the AWS agentic development environment: an IDE (a fork of VS Code), a CLI and a web app. It became generally available on 2025-11-17. Its main ideas:', he: '[[Kiro]] הוא סביבת הפיתוח האגנטית של AWS: IDE (fork של VS Code), CLI ואפליקציית web. הוא הפך לזמין לכולם ב-2025-11-17. הרעיונות המרכזיים שלו:' },
        { t: 'list', en: ['**[[Spec]]s** — spec-driven development. The agent first writes requirements, then a design, then a task list, and only then code. You review each step.', '**[[Steering]] files** — permanent rules of the project (style, architecture, "never touch this folder").', '**Hooks** — agent actions that start by themselves on an event, for example "when a file is saved, update its tests".', '**MCP servers** — the same protocol you learned in module 6, so Kiro can use external tools. There is even an AgentCore MCP server that lets a coding assistant manage AgentCore for you.'], he: ['**[[Spec]]s** — פיתוח מונחה spec. הסוכן קודם כותב דרישות, אחר כך תכנון, אחר כך רשימת משימות, ורק אז קוד. אתה בודק כל שלב.', '**קובצי [[Steering]]** — כללים קבועים של הפרויקט (סגנון, ארכיטקטורה, "אל תיגע בתיקייה הזו").', '**Hooks** — פעולות של הסוכן שמתחילות לבד בעקבות אירוע, לדוגמה "כשקובץ נשמר, עדכן את הבדיקות שלו".', '**MCP servers** — אותו פרוטוקול שלמדת במודול 6, כך ש-Kiro יכול להשתמש בכלים חיצוניים. יש אפילו AgentCore MCP server שמאפשר לעוזר קוד לנהל את AgentCore בשבילך.'] },
        { t: 'p', en: '[[Amazon Q Developer]] was the coding assistant before Kiro (and before it, the name was CodeWhisperer). It is being retired:', he: '[[Amazon Q Developer]] היה עוזר הקוד לפני Kiro (ולפניו השם היה CodeWhisperer). הוא בדרך החוצה:' },
        { t: 'table', head: { en: ['Date', 'What happened / happens'], he: ['תאריך', 'מה קרה / יקרה'] }, rows: {
          en: [['2026-04-30', 'AWS announced end of support for the Q Developer IDE plugins and paid subscriptions.'], ['2026-05-15', 'New sign-ups blocked (new free accounts and new subscriptions).'], ['2027-04-30', 'End of support for the IDE plugins (VS Code, JetBrains, Eclipse, Visual Studio) and paid plans.'], ['Not affected', 'Q Developer chat inside the AWS Management Console, the AWS website and docs, the Console Mobile App, and the Slack / Microsoft Teams chat apps.']],
          he: [['2026-04-30', 'AWS הכריזה על סיום תמיכה בתוספי ה-IDE של Q Developer ובמנויים בתשלום.'], ['2026-05-15', 'הרשמות חדשות נחסמו (חשבונות חינמיים חדשים ומנויים חדשים).'], ['2027-04-30', 'סיום תמיכה בתוספי ה-IDE (VS Code, JetBrains, Eclipse, Visual Studio) ובתוכניות בתשלום.'], ['לא מושפע', 'הצ׳אט של Q Developer בתוך ה-AWS Management Console, אתר AWS והתיעוד, ה-Console Mobile App, ואפליקציות הצ׳אט ב-Slack / Microsoft Teams.']] } },
        { t: 'note', kind: 'info', en: 'Two more moves from the same change. The old Q Developer CLI is now **Kiro CLI**. And the code-upgrade features (Java upgrades, .NET porting) did not go to Kiro: they moved to [[AWS Transform]], the agentic modernization service.', he: 'עוד שני מהלכים מאותו שינוי. ה-CLI הישן של Q Developer הוא עכשיו **Kiro CLI**. ויכולות שדרוג הקוד (שדרוג Java, המרת .NET) לא עברו ל-Kiro: הן עברו ל-[[AWS Transform]], שירות המודרניזציה האגנטי.' },
        { t: 'note', kind: 'tip', en: 'Kiro pricing is **credit based**, per user per month. Example numbers from November 2026: Free (50 credits), Pro $20 (1,000 credits), Pro+ $40, Pro Max $100, Power $200, and extra credits at $0.04 each. Do not memorize the numbers, memorize the model: you buy credits, agent work spends them.', he: 'התמחור של Kiro **מבוסס קרדיטים**, למשתמש לחודש. מספרים לדוגמה מנובמבר 2026: Free (50 קרדיטים), Pro ב-$20 (1,000 קרדיטים), Pro+ ב-$40, Pro Max ב-$100, Power ב-$200, וקרדיטים נוספים ב-$0.04 לכל אחד. לא לשנן את המספרים אלא את המודל: קונים קרדיטים, ועבודת הסוכן מוציאה אותם.' },
        { t: 'quiz', q: { en: 'In November 2026 a new developer joins and asks you to "install Amazon Q Developer in VS Code, like in the tutorial I found". What do you tell them?', he: 'בנובמבר 2026 מצטרף מפתח חדש ומבקש "להתקין Amazon Q Developer ב-VS Code, כמו בטוטוריאל שמצאתי". מה אתה אומר לו?' },
          options: { en: ['Fine, it is the current AWS coding assistant', 'The tutorial is old: new sign-ups are blocked and the plugins end on 2027-04-30. Use Kiro.', 'Q Developer was renamed Amazon Q Business, install that', 'Use the Bedrock console playground instead, it is the same thing'], he: ['בסדר, זה עוזר הקוד העדכני של AWS', 'הטוטוריאל ישן: הרשמות חדשות חסומות והתוספים מסתיימים ב-2027-04-30. תשתמש ב-Kiro.', 'Q Developer שינה שם ל-Amazon Q Business, תתקין את זה', 'תשתמש ב-playground ב-console של Bedrock, זה אותו דבר'] },
          answer: 1, explain: { en: 'New Q Developer accounts and subscriptions have been blocked since 2026-05-15, and the IDE plugins reach end of support on 2027-04-30. Kiro is the named successor. Q Business is a different product (a company assistant), not a new name for Q Developer.', he: 'חשבונות ומנויים חדשים של Q Developer חסומים מ-2026-05-15, ותוספי ה-IDE מגיעים לסיום תמיכה ב-2027-04-30. Kiro הוא היורש הרשמי. Q Business הוא מוצר אחר (עוזר ארגוני), לא שם חדש של Q Developer.' } },
        { t: 'h', en: 'Business assistants: Amazon Q Business → AWS Quick', he: 'עוזרים עסקיים: Amazon Q Business ← AWS Quick' },
        { t: 'p', en: '[[Amazon Q Business]] is a managed assistant that answers employees from company data. Its words: an **application**, an **index** filled by **data source connectors**, **plugins** (actions in other apps) and **Q Apps** (small no-code apps). Status: [[Maintenance]], announced 2026-06-30, closed to new customers from 2026-07-30. Existing customers get fixes only.', he: '[[Amazon Q Business]] הוא עוזר מנוהל שעונה לעובדים מתוך מידע של החברה. המילים שלו: **application**, **index** שמתמלא מ-**data source connectors**, **plugins** (פעולות באפליקציות אחרות) ו-**Q Apps** (אפליקציות קטנות בלי קוד). סטטוס: [[Maintenance]], הוכרז ב-2026-06-30, סגור ללקוחות חדשים מ-2026-07-30. לקוחות קיימים מקבלים רק תיקונים.' },
        { t: 'p', en: 'The successor is [[AWS Quick]]: an AI workspace for business users. It grew out of the BI product QuickSight, and its name changed three times:', he: 'היורש הוא [[AWS Quick]]: סביבת AI למשתמשים עסקיים. הוא צמח ממוצר ה-BI בשם QuickSight, והשם שלו השתנה שלוש פעמים:' },
        { t: 'flow', steps: { en: ['Amazon QuickSight (BI dashboards)', 'Amazon Quick Suite (October 2025)', 'Amazon Quick (2026)', 'AWS Quick (2026-11-09)'], he: ['Amazon QuickSight (דשבורדים של BI)', 'Amazon Quick Suite (אוקטובר 2025)', 'Amazon Quick (2026)', 'AWS Quick (2026-11-09)'] }, caption: { en: 'All four names appear in blogs. They are the same product line.', he: 'כל ארבעת השמות מופיעים בבלוגים. זה אותו קו מוצרים.' } },
        { t: 'table', head: { en: ['Part of AWS Quick', 'What it is'], he: ['חלק של AWS Quick', 'מה זה'] }, rows: {
          en: [['AWS Quick Sight', 'The BI and dashboards part (the old QuickSight). The `quicksight` APIs and SDKs keep working.'], ['AWS Quick Index', 'Connects documents and data sources so answers are grounded in company data.'], ['AWS Quick Research', 'Research reports with citations.'], ['AWS Quick Flows', 'Automates repetitive tasks. Old Q Apps must be rebuilt as Quick Flows.'], ['AWS Quick Automate', 'Multi-step business process automation with agents.']],
          he: [['AWS Quick Sight', 'חלק ה-BI והדשבורדים (QuickSight הישן). ה-APIs וה-SDKs של `quicksight` ממשיכים לעבוד.'], ['AWS Quick Index', 'מחבר מסמכים ומקורות מידע כדי שהתשובות יהיו מעוגנות במידע של החברה.'], ['AWS Quick Research', 'דוחות מחקר עם ציטוטים.'], ['AWS Quick Flows', 'אוטומציה של משימות חוזרות. Q Apps ישנים צריך לבנות מחדש כ-Quick Flows.'], ['AWS Quick Automate', 'אוטומציה של תהליכים עסקיים מרובי שלבים עם סוכנים.']] } },
        { t: 'note', kind: 'warn', en: 'Migration from Q Business is not a button. It starts with **Bring Your Own Index (BYOI)**: an existing Q Business index is connected to Quick as a knowledge base (at most two indexes per Region). Q Apps must be rebuilt, and guardrails, actions and the user store do **not** carry over. If a manager says "we will just switch", this is the detail to raise.', he: 'מעבר מ-Q Business הוא לא כפתור. הוא מתחיל ב-**Bring Your Own Index (BYOI)**: index קיים של Q Business מתחבר ל-Quick כ-knowledge base (לכל היותר שני indexes ב-Region). Q Apps צריך לבנות מחדש, ו-guardrails, actions ומאגר המשתמשים **לא** עוברים. אם מנהל אומר "פשוט נעבור", זה הפרט שצריך להעלות.' },
        { t: 'h', en: 'Build or buy: where does AgentCore fit?', he: 'לבנות או לקנות: איפה AgentCore נכנס?' },
        { t: 'p', en: 'AWS Quick, Kiro and the "frontier agents" (AWS DevOps Agent, AWS Security Agent, and others in preview) are **finished products**: you configure them and use them. [[Bedrock]] and [[AgentCore]] are **building blocks**: you write the application. The interview question is always the same: is this a standard need of employees (buy), or is the agent part of your own product (build)?', he: 'AWS Quick, Kiro וה-"frontier agents" (AWS DevOps Agent, AWS Security Agent ועוד כמה ב-preview) הם **מוצרים מוגמרים**: מגדירים ומשתמשים. [[Bedrock]] ו-[[AgentCore]] הם **אבני בניין**: אתה כותב את האפליקציה. שאלת הראיון תמיד זהה: האם זה צורך סטנדרטי של עובדים (לקנות), או שהסוכן הוא חלק מהמוצר שלך (לבנות)?' },
        { t: 'match', prompt: { en: 'An old name appears in a blog post. Match it to what you should use or say today.', he: 'שם ישן מופיע בבלוג. התאם אותו למה שמשתמשים או אומרים היום.' }, pairs: [
          { a: 'Amazon CodeWhisperer', b: { en: 'Became Q Developer, now replaced by Kiro', he: 'הפך ל-Q Developer, ועכשיו Kiro מחליף אותו' } },
          { a: 'Amazon Q Business', b: { en: 'Maintenance; successor is AWS Quick', he: 'Maintenance; היורש הוא AWS Quick' } },
          { a: 'Amazon QuickSight', b: { en: 'AWS Quick Sight, the BI part of AWS Quick', he: 'AWS Quick Sight, חלק ה-BI של AWS Quick' } },
          { a: 'Amazon Bedrock Agents', b: { en: 'Agents Classic (maintenance); use AgentCore', he: 'Agents Classic (maintenance); משתמשים ב-AgentCore' } },
          { a: 'Amazon Bedrock Studio', b: { en: 'Amazon Bedrock in SageMaker Unified Studio', he: 'Amazon Bedrock in SageMaker Unified Studio' } },
          { a: { en: 'Q Developer "transform" for Java / .NET', he: 'ה-"transform" של Q Developer ל-Java / .NET' }, b: 'AWS Transform' }
        ] },
        { t: 'quiz', q: { en: 'An HR department wants employees to ask questions about HR policies stored in SharePoint. No custom product, no developers available, and the company is a new AWS customer. What do you recommend in November 2026?', he: 'מחלקת HR רוצה שעובדים ישאלו שאלות על נהלי HR ששמורים ב-SharePoint. אין מוצר ייעודי, אין מפתחים פנויים, והחברה היא לקוח חדש של AWS. מה תמליץ בנובמבר 2026?' },
          options: { en: ['Amazon Q Business, it was built exactly for this', 'Amazon Kendra with a custom web front end', 'Bedrock Agents Classic with a knowledge base', 'AWS Quick, the current business-user workspace that connects to company data'], he: ['Amazon Q Business, הוא נבנה בדיוק לזה', 'Amazon Kendra עם ממשק web משלך', 'Bedrock Agents Classic עם knowledge base', 'AWS Quick, סביבת העבודה העדכנית למשתמשים עסקיים שמתחברת למידע של החברה'] },
          answer: 3, explain: { en: 'Q Business, Kendra and Agents Classic are all in maintenance and closed to new customers since 2026-07-30, so a new customer cannot even start with them. AWS Quick is the named successor of Q Business and needs no developers. If the assistant had to be part of a product, you would build with a Bedrock Managed Knowledge Base and AgentCore.', he: 'Q Business, Kendra ו-Agents Classic כולם ב-maintenance וסגורים ללקוחות חדשים מ-2026-07-30, אז לקוח חדש בכלל לא יכול להתחיל איתם. AWS Quick הוא היורש הרשמי של Q Business ולא דורש מפתחים. אם העוזר היה צריך להיות חלק ממוצר, היית בונה עם Bedrock Managed Knowledge Base ו-AgentCore.' } },
        { t: 'order', prompt: { en: 'Put the names of the AWS business-intelligence-turned-AI-workspace product in historical order, oldest first.', he: 'סדר את השמות של מוצר ה-BI שהפך לסביבת AI לפי סדר היסטורי, מהישן לחדש.' }, items: { en: ['Amazon QuickSight', 'Amazon Quick Suite', 'Amazon Quick', 'AWS Quick'], he: ['Amazon QuickSight', 'Amazon Quick Suite', 'Amazon Quick', 'AWS Quick'] },
          explain: { en: 'QuickSight → Quick Suite (October 2025) → Amazon Quick (2026) → AWS Quick (announced 2026-11-09). The Q Business maintenance notice still calls it "Amazon Quick".', he: 'QuickSight ← Quick Suite (אוקטובר 2025) ← Amazon Quick (2026) ← AWS Quick (הוכרז ב-2026-11-09). הודעת ה-maintenance של Q Business עדיין קוראת לו "Amazon Quick".' } },
        { t: 'quiz', q: { en: 'Which statements about the Q Developer retirement are correct? Pick all that apply.', he: 'אילו משפטים על היציאה לפנסיה של Q Developer נכונים? בחר את כל הנכונים.' },
          options: { en: ['The IDE plugins reach end of support on 2027-04-30', 'Q Developer chat in the AWS Management Console is not affected', 'Java upgrade and .NET porting features moved to AWS Transform', 'Kiro has a native Eclipse plugin that replaces the Q one'], he: ['תוספי ה-IDE מגיעים לסיום תמיכה ב-2027-04-30', 'הצ׳אט של Q Developer ב-AWS Management Console לא מושפע', 'יכולות שדרוג Java והמרת .NET עברו ל-AWS Transform', 'ל-Kiro יש תוסף Eclipse מקורי שמחליף את של Q'] },
          answer: [0, 1, 2], explain: { en: 'Kiro has no native Visual Studio or Eclipse plugin; JetBrains users connect Kiro CLI. The other three are exactly what AWS announced.', he: 'ל-Kiro אין תוסף מקורי ל-Visual Studio או ל-Eclipse; משתמשי JetBrains מחברים את Kiro CLI. שלושת האחרים הם בדיוק מה ש-AWS הודיעה.' } },
        { t: 'reveal', q: { en: 'Your CTO read that "AWS is killing Q" and asks whether the company\'s Bedrock application is at risk. What do you answer?', he: 'ה-CTO שלך קרא ש-"AWS הורגת את Q" ושואל אם אפליקציית ה-Bedrock של החברה בסיכון. מה אתה עונה?' },
          a: { en: 'No. Three separate things share the letter Q. Q Developer (coding assistant) is in sunset and Kiro replaces it. Q Business (company assistant) is in maintenance and AWS Quick replaces it. Neither is Bedrock. Bedrock itself, Knowledge Bases and Guardrails are active. The only Bedrock part that changed status is Bedrock Agents, now "Agents Classic" in maintenance, with AgentCore as the path forward. So I would check one thing: do we use Agents Classic anywhere? If yes, it keeps working, but new work should go to AgentCore.', he: 'לא. שלושה דברים נפרדים חולקים את האות Q. Q Developer (עוזר קוד) ב-sunset ו-Kiro מחליף אותו. Q Business (עוזר ארגוני) ב-maintenance ו-AWS Quick מחליף אותו. אף אחד מהם הוא לא Bedrock. Bedrock עצמו, Knowledge Bases ו-Guardrails פעילים. החלק היחיד ב-Bedrock ששינה סטטוס הוא Bedrock Agents, עכשיו "Agents Classic" ב-maintenance, כש-AgentCore הוא הדרך קדימה. אז הייתי בודק דבר אחד: האם אנחנו משתמשים ב-Agents Classic איפשהו? אם כן, זה ממשיך לעבוד, אבל עבודה חדשה צריכה ללכת ל-AgentCore.' } }
      ]
    },
    {
      id: 'm14l3', minutes: 14,
      title: { en: 'Amazon Nova, Titan, Data Automation, S3 Vectors, PartyRock', he: 'Amazon Nova, Titan, Data Automation, S3 Vectors, PartyRock' },
      blocks: [
        { t: 'p', en: 'Most examples in this course used Claude. But Amazon has its own models and a few model-side services around them. You will meet them in price comparisons, in RAG designs and in exam questions.', he: 'רוב הדוגמאות בקורס השתמשו ב-Claude. אבל ל-Amazon יש מודלים משלה וכמה שירותים בצד המודל סביבם. תפגוש אותם בהשוואות מחיר, בתכנון RAG ובשאלות מבחן.' },
        { t: 'h', en: 'The Amazon Nova family', he: 'משפחת Amazon Nova' },
        { t: 'p', en: '[[Amazon Nova]] is Amazon\'s own model family. You call it like any other Bedrock model (Converse or InvokeModel on `bedrock-runtime`) and pay per token. Status in November 2026:', he: '[[Amazon Nova]] היא משפחת המודלים של Amazon עצמה. קוראים לה כמו לכל מודל אחר ב-Bedrock (Converse או InvokeModel על `bedrock-runtime`) ומשלמים לפי טוקן. הסטטוס בנובמבר 2026:' },
        { t: 'table', head: { en: ['Model', 'What it is for', 'Status'], he: ['מודל', 'בשביל מה', 'סטטוס'] }, rows: {
          en: [['Nova Micro', 'Text only. The cheapest and fastest of the first generation.', 'Active'], ['Nova Lite, Nova Pro', 'Text, image and video input. Lite = cheap and fast, Pro = stronger.', 'Active'], ['Nova 2 Lite', 'Reasoning model with extended thinking, a 1M-token [[Context window]], built-in web grounding and code interpreter. AWS recommends it as the upgrade from Nova Lite and Pro.', 'Active'], ['Nova 2 Sonic, Nova 2.5 Sonic', 'Speech-to-speech: audio in, audio out, for voice agents. 2.5 is the newest.', 'Active'], ['Nova Multimodal Embeddings', 'One [[Embedding]] model for text, images, documents, video and audio.', 'Active'], ['Nova Sonic (v1)', 'First speech-to-speech model.', 'EOL 2026-09-14'], ['Nova Canvas (images), Nova Reel (video)', 'Image and video generation.', 'EOL 2026-09-30']],
          he: [['Nova Micro', 'טקסט בלבד. הזול והמהיר ביותר בדור הראשון.', 'Active'], ['Nova Lite, Nova Pro', 'קלט של טקסט, תמונה ווידאו. Lite = זול ומהיר, Pro = חזק יותר.', 'Active'], ['Nova 2 Lite', 'מודל reasoning עם extended thinking, [[Context window]] של מיליון טוקנים, web grounding ו-code interpreter מובנים. AWS ממליצה עליו כשדרוג מ-Nova Lite ו-Pro.', 'Active'], ['Nova 2 Sonic, Nova 2.5 Sonic', 'דיבור-לדיבור: אודיו נכנס, אודיו יוצא, לסוכנים קוליים. 2.5 הוא החדש ביותר.', 'Active'], ['Nova Multimodal Embeddings', 'מודל [[Embedding]] אחד לטקסט, תמונות, מסמכים, וידאו ואודיו.', 'Active'], ['Nova Sonic (v1)', 'מודל הדיבור-לדיבור הראשון.', 'EOL 2026-09-14'], ['Nova Canvas (תמונות), Nova Reel (וידאו)', 'יצירת תמונות ווידאו.', 'EOL 2026-09-30']] } },
        { t: 'note', kind: 'warn', en: 'Nova Canvas and Nova Reel are a good lesson in reading status. Their pages are still in the docs, old tutorials still use them, but since 2026-09-30 a call fails with `ResourceNotFoundException`. Nova Premier, which older posts recommend, is also no longer in the Bedrock list of Amazon models. Before you copy a model ID from a blog, open the **model card** and look at the lifecycle line.', he: 'Nova Canvas ו-Nova Reel הם שיעור טוב בקריאת סטטוס. הדפים שלהם עדיין בתיעוד, טוטוריאלים ישנים עדיין משתמשים בהם, אבל מאז 2026-09-30 קריאה נכשלת עם `ResourceNotFoundException`. גם Nova Premier, שפוסטים ישנים ממליצים עליו, כבר לא ברשימת מודלי Amazon ב-Bedrock. לפני שמעתיקים model ID מבלוג, פותחים את ה-**model card** ומסתכלים על שורת ה-lifecycle.' },
        { t: 'fill', prompt: { en: 'Call Nova 2 Lite through the Converse API. Fill in the client and the model ID.', he: 'קרא ל-Nova 2 Lite דרך Converse API. השלם את ה-client ואת ה-model ID.' },
          lang: 'python', code: 'import boto3\n\nclient = boto3.client("{{1}}", region_name="us-east-1")\nresponse = client.converse(\n    modelId="amazon.{{2}}-v1:0",\n    messages=[{"role": "user", "content": [{"text": "Summarize our return policy in one line."}]}],\n    inferenceConfig={"maxTokens": 200},\n)\nprint(response["output"]["message"]["content"][0]["text"])', blanks: [ { accept: ['bedrock-runtime'], hint: { en: 'the inference client', he: 'ה-client של inference' } }, { accept: ['nova-2-lite'], hint: { en: 'family, generation, size, with dashes', he: 'משפחה, דור, גודל, עם מקפים' } } ],
          explain: { en: 'Nova is "just another model" behind the same Converse call. That is the point of Bedrock: you can compare Claude and Nova on your task by changing one string, and let cost and evaluations decide.', he: 'Nova הוא "עוד מודל" מאחורי אותה קריאת Converse. זו הנקודה של Bedrock: אפשר להשוות בין Claude ל-Nova על המשימה שלך בשינוי מחרוזת אחת, ולתת לעלות ול-evaluations להחליט.' } },
        { t: 'p', en: 'Two more names with "Nova" that are **not** models you chat with:', he: 'עוד שני שמות עם "Nova" שהם **לא** מודלים שמדברים איתם:' },
        { t: 'list', en: ['[[Nova Act]] — a service and SDK for agents that drive a real web browser to automate work in web interfaces. Generally available since December 2025. It is billed per agent hour (example from November 2026: $4.75). It can also drive the AgentCore Browser that you met in module 8.', '**Nova Forge** — a subscription service for building your own frontier model from Nova checkpoints with your data. This is for a handful of very large customers; just know the name.'], he: ['[[Nova Act]] — שירות ו-SDK לסוכנים שמפעילים דפדפן אמיתי כדי לבצע אוטומציה של עבודה בממשקי web. זמין לכולם מדצמבר 2025. מחויב לפי שעת סוכן (דוגמה מנובמבר 2026: $4.75). הוא יכול גם להפעיל את AgentCore Browser שפגשת במודול 8.', '**Nova Forge** — שירות מנוי לבניית frontier model משלך מתוך checkpoints של Nova עם הדאטה שלך. זה מיועד לקומץ לקוחות גדולים מאוד; מספיק להכיר את השם.'] },
        { t: 'quiz', q: { en: 'You design a phone support line where the caller talks and the agent answers by voice with very low delay. Which model family is built for exactly this?', he: 'אתה מתכנן קו תמיכה טלפוני שבו המתקשר מדבר והסוכן עונה בקול עם השהיה נמוכה מאוד. איזו משפחת מודלים בנויה בדיוק לזה?' },
          options: { en: ['Nova 2 Sonic / Nova 2.5 Sonic (speech-to-speech)', 'Nova Micro', 'Titan Text Embeddings V2', 'Nova Canvas'], he: ['Nova 2 Sonic / Nova 2.5 Sonic (דיבור-לדיבור)', 'Nova Micro', 'Titan Text Embeddings V2', 'Nova Canvas'] },
          answer: 0, explain: { en: 'Sonic models take audio in and give audio out in one model, which removes the separate speech-to-text and text-to-speech hops. Nova Micro is text only, Titan V2 only makes embeddings, and Nova Canvas was an image model that is now EOL.', he: 'מודלי Sonic מקבלים אודיו ומחזירים אודיו במודל אחד, וכך נחסכות הקפיצות הנפרדות של דיבור-לטקסט וטקסט-לדיבור. Nova Micro הוא טקסט בלבד, Titan V2 רק מייצר embeddings, ו-Nova Canvas היה מודל תמונות שעכשיו EOL.' } },
        { t: 'h', en: 'Titan: today it means embeddings', he: 'Titan: היום זה אומר embeddings' },
        { t: 'p', en: '[[Titan]] is Amazon\'s older family. The Titan text and image generators are gone from the Bedrock list; what remains are the embeddings models. The one you will meet everywhere is **Titan Text Embeddings V2** (`amazon.titan-embed-text-v2:0`): input up to 8K tokens, output vectors of **1024** (default), **512** or **256** dimensions, and it works with `InvokeModel` only (Converse is for chat models).', he: '[[Titan]] היא המשפחה הישנה יותר של Amazon. מחוללי הטקסט והתמונות של Titan נעלמו מהרשימה של Bedrock; מה שנשאר הם מודלי ה-embeddings. זה שתפגוש בכל מקום הוא **Titan Text Embeddings V2** (`amazon.titan-embed-text-v2:0`): קלט עד 8K טוקנים, וקטורי פלט של **1024** (ברירת מחדל), **512** או **256** ממדים, והוא עובד רק עם `InvokeModel` (Converse מיועד למודלי צ׳אט).' },
        { t: 'note', kind: 'tip', en: 'Dimensions are a trade-off. Fewer dimensions = smaller vectors = cheaper storage and faster search, with a small loss of accuracy. But you choose **once**: the index is created for one dimension, and a Bedrock Managed Knowledge Base accepts a custom embedding model only at 1024. Changing the embedding model later means embedding every document again.', he: 'ממדים הם trade-off. פחות ממדים = וקטורים קטנים יותר = אחסון זול יותר וחיפוש מהיר יותר, עם אובדן קטן בדיוק. אבל בוחרים **פעם אחת**: ה-index נוצר לממד אחד, ו-Bedrock Managed Knowledge Base מקבל מודל embedding מותאם רק ב-1024. החלפת מודל ה-embedding אחר כך אומרת לעשות embedding מחדש לכל מסמך.' },
        { t: 'fill', prompt: { en: 'Create an embedding with Titan Text Embeddings V2. Fill in the API call and the model ID. (The body fields are on the model card.)', he: 'צור embedding עם Titan Text Embeddings V2. השלם את קריאת ה-API ואת ה-model ID. (שדות ה-body מופיעים ב-model card.)' },
          lang: 'python', code: 'import boto3, json\n\nbrt = boto3.client("bedrock-runtime")\nresponse = brt.{{1}}(\n    modelId="amazon.{{2}}:0",\n    body=json.dumps(request_body),   # the text to embed, see the model card\n)\nresult = json.loads(response["body"].read())', blanks: [ { accept: ['invoke_model'], hint: { en: 'embedding models do not support Converse', he: 'מודלי embedding לא תומכים ב-Converse' } }, { accept: ['titan-embed-text-v2'], hint: { en: 'titan, embed, text, v2', he: 'titan, embed, text, v2' } } ],
          explain: { en: 'Converse is a chat format: messages in, a message out. An embedding model returns numbers, not a message, so it lives on InvokeModel with its own JSON body.', he: 'Converse הוא פורמט צ׳אט: הודעות נכנסות, הודעה יוצאת. מודל embedding מחזיר מספרים ולא הודעה, אז הוא חי על InvokeModel עם JSON body משלו.' } },
        { t: 'h', en: 'Bedrock Data Automation (BDA)', he: 'Bedrock Data Automation (BDA)' },
        { t: 'p', en: '[[Bedrock Data Automation]] turns unstructured **documents, images, audio and video** into structured output with one API. Typical uses: reading invoices and forms, analyzing media, and preparing messy files for [[RAG]].', he: '[[Bedrock Data Automation]] הופך **מסמכים, תמונות, אודיו ווידאו** לא מובנים לפלט מובנה עם API אחד. שימושים טיפוסיים: קריאת חשבוניות וטפסים, ניתוח מדיה, והכנת קבצים מבולגנים ל-[[RAG]].' },
        { t: 'list', en: ['A **project** stores the output configuration.', '**Standard output** = the ready-made result for each type of file: text, tables, summaries, moderation.', '**Custom output** uses a [[Blueprint]]: a schema of the exact fields you want (invoice number, total, due date). Blueprints have DEVELOPMENT and LIVE stages.', 'Results carry **confidence scores** and **bounding boxes**, so you can show a human where each value came from.'], he: ['**project** שומר את הגדרות הפלט.', '**Standard output** = התוצאה המוכנה לכל סוג קובץ: טקסט, טבלאות, סיכומים, moderation.', '**Custom output** משתמש ב-[[Blueprint]]: סכמה של השדות המדויקים שרוצים (מספר חשבונית, סכום, תאריך תשלום). ל-blueprints יש שלבי DEVELOPMENT ו-LIVE.', 'התוצאות כוללות **confidence scores** ו-**bounding boxes**, כך שאפשר להראות לאדם מאיפה הגיע כל ערך.'] },
        { t: 'code', lang: 'python', code: 'import boto3\n\n# build time: projects and blueprints\nbda = boto3.client("bedrock-data-automation")\n#   CreateDataAutomationProject, CreateBlueprint\n\n# run time: process files\nbda_rt = boto3.client("bedrock-data-automation-runtime")\n#   InvokeDataAutomationAsync  -> all file types, S3 in / S3 out\n#   GetDataAutomationStatus    -> poll until the job is done\n#   InvokeDataAutomation       -> synchronous, images only\n# every call needs a dataAutomationProfileArn and a project ARN or blueprint ARNs', caption: { en: 'The BDA API map. The same build/run split as bedrock and bedrock-runtime.', he: 'מפת ה-API של BDA. אותה חלוקת build/run כמו bedrock ו-bedrock-runtime.' } },
        { t: 'p', en: 'BDA is priced by what it processes: per page, per image, per minute of audio or video (examples from November 2026: $0.010 per page for standard output, $0.040 per page for custom output). It is also one of the three **parsers** a customer-managed Knowledge Base can use: the default text parser, BDA, or a foundation model as parser.', he: 'BDA מתומחר לפי מה שהוא מעבד: לדף, לתמונה, לדקת אודיו או וידאו (דוגמאות מנובמבר 2026: $0.010 לדף ב-standard output, $0.040 לדף ב-custom output). הוא גם אחד משלושת ה-**parsers** ש-Knowledge Base מסוג customer-managed יכול להשתמש בהם: ה-parser הטקסטואלי של ברירת המחדל, BDA, או foundation model בתור parser.' },
        { t: 'quiz', q: { en: 'An insurer receives 40,000 scanned claim forms per day and needs the same 12 fields from each, with a confidence score so low-confidence forms go to a human. What fits best?', he: 'חברת ביטוח מקבלת 40,000 טופסי תביעה סרוקים ביום וצריכה את אותם 12 שדות מכל אחד, עם confidence score כדי שטפסים עם ביטחון נמוך יעברו לאדם. מה הכי מתאים?' },
          options: { en: ['Send every scan to a chat model with a long prompt and parse the reply with regex', 'A Knowledge Base with semantic search over the forms', 'Bedrock Data Automation with a blueprint for the 12 fields', 'Fine-tune Nova Micro on old forms'], he: ['לשלוח כל סריקה למודל צ׳אט עם פרומפט ארוך ולפרסר את התשובה עם regex', 'Knowledge Base עם semantic search על הטפסים', 'Bedrock Data Automation עם blueprint ל-12 השדות', 'Fine-tuning ל-Nova Micro על טפסים ישנים'] },
          answer: 2, explain: { en: 'A fixed set of fields, at volume, with confidence scores and bounding boxes is exactly what a BDA blueprint gives, at a per-page price. A chat model plus regex has no confidence score and breaks on format drift. A knowledge base answers questions; it does not extract fields. Nova Micro is text only and cannot read scans.', he: 'קבוצה קבועה של שדות, בנפח גדול, עם confidence scores ו-bounding boxes, זה בדיוק מה ש-blueprint של BDA נותן, במחיר לדף. מודל צ׳אט עם regex לא נותן confidence score ונשבר כשהפורמט זז. Knowledge base עונה על שאלות; הוא לא מחלץ שדות. Nova Micro הוא טקסט בלבד ולא יכול לקרוא סריקות.' } },
        { t: 'h', en: 'Amazon S3 Vectors', he: 'Amazon S3 Vectors' },
        { t: 'p', en: '[[S3 Vectors]] is vector storage and similarity search built into S3 (generally available since 2025-12-02). You create a **vector bucket**, then **vector indexes** inside it (each with a fixed dimension and distance metric), and store vectors with a key and metadata. The boto3 client is `s3vectors`.', he: '[[S3 Vectors]] הוא אחסון וקטורים וחיפוש דמיון שבנויים בתוך S3 (זמין לכולם מ-2025-12-02). יוצרים **vector bucket**, אחר כך **vector indexes** בתוכו (לכל אחד ממד קבוע ו-distance metric), ושומרים וקטורים עם key ו-metadata. ה-boto3 client הוא `s3vectors`.' },
        { t: 'order', prompt: { en: 'Put the S3 Vectors API calls in the order you would use them in a new project.', he: 'סדר את קריאות ה-API של S3 Vectors לפי הסדר שבו תשתמש בהן בפרויקט חדש.' }, items: { en: ['CreateVectorBucket', 'CreateIndex (fix the dimension and distance metric)', 'PutVectors (up to 500 vectors per call)', 'QueryVectors (find the nearest vectors)'], he: ['CreateVectorBucket', 'CreateIndex (קובעים ממד ו-distance metric)', 'PutVectors (עד 500 וקטורים בקריאה)', 'QueryVectors (מוצאים את הוקטורים הקרובים ביותר)'] },
          explain: { en: 'Bucket → index → write → query. The dimension is fixed at CreateIndex, which is why the embedding model must be chosen before the index.', he: 'Bucket ← index ← כתיבה ← שאילתה. הממד נקבע ב-CreateIndex, ולכן חייבים לבחור את מודל ה-embedding לפני ה-index.' } },
        { t: 'table', head: { en: ['', 'S3 Vectors', 'OpenSearch Serverless'], he: ['', 'S3 Vectors', 'OpenSearch Serverless'] }, rows: {
          en: [['Cost model', 'Pay for storage, writes and queries. No cluster running all the time.', 'Capacity that runs all the time.'], ['Hybrid search (keyword + meaning) in a Knowledge Base', 'No', 'Yes'], ['Metadata in a Knowledge Base', '1 KB custom metadata and 35 keys per vector; no `startsWith` / `stringContains` filters', 'Richer filters'], ['Hierarchical chunking', 'Not recommended', 'Fine'], ['Best for', 'Large, cost-sensitive, less latency-critical RAG and agent memory', 'Low-latency, feature-rich search']],
          he: [['מודל עלות', 'משלמים על אחסון, כתיבות ושאילתות. אין cluster שרץ כל הזמן.', 'קיבולת שרצה כל הזמן.'], ['Hybrid search (מילות מפתח + משמעות) ב-Knowledge Base', 'לא', 'כן'], ['Metadata ב-Knowledge Base', '1 KB של metadata מותאם ו-35 keys לוקטור; בלי פילטרים `startsWith` / `stringContains`', 'פילטרים עשירים יותר'], ['Hierarchical chunking', 'לא מומלץ', 'בסדר'], ['הכי טוב בשביל', 'RAG וזיכרון סוכנים גדולים, רגישים לעלות ופחות רגישים ל-latency', 'חיפוש עם latency נמוך והרבה יכולות']] } },
        { t: 'console', service: 'Amazon Bedrock', nav: ['#Build', 'Knowledge bases', 'Guardrails', 'Prompt management'], active: 'Knowledge bases',
          crumbs: ['Amazon Bedrock', 'Knowledge bases', 'Create knowledge base'],
          task: { en: 'A small team builds an internal FAQ bot over 3,000 text documents. Budget is tight, traffic is low, and keyword search is not needed. Configure the storage step of a customer-managed knowledge base: use Titan Text Embeddings V2 at its default dimension, and let Bedrock create the cheapest vector store for this case.', he: 'צוות קטן בונה בוט FAQ פנימי על 3,000 מסמכי טקסט. התקציב הדוק, התעבורה נמוכה, ואין צורך בחיפוש לפי מילות מפתח. הגדר את שלב האחסון של knowledge base מסוג customer-managed: השתמש ב-Titan Text Embeddings V2 בממד ברירת המחדל שלו, ותן ל-Bedrock ליצור את ה-vector store הזול ביותר למקרה הזה.' },
          heading: 'Configure data storage and processing',
          panels: [
            { title: 'Embeddings model', n: 1, fields: [
              { label: 'Embeddings model', type: 'select', options: ['Titan Embeddings G1 - Text', 'Titan Text Embeddings V2', 'Cohere Embed English v3', 'Cohere Embed Multilingual v3'], value: 'Titan Embeddings G1 - Text', expect: 'Titan Text Embeddings V2', hint: { en: 'The brief names the model.', he: 'התדריך מציין את המודל.' } },
              { label: 'Vector dimensions', type: 'select', options: ['256', '512', '1024'], value: '256', expect: '1024', n: 2, hint: { en: 'The default dimension of Titan V2.', he: 'ממד ברירת המחדל של Titan V2.' } } ] },
            { title: 'Vector database', n: 3, fields: [
              { label: 'Vector store creation method', type: 'radio', options: ['Choose a vector store you have created', 'Quick create a new vector store'], value: 'Choose a vector store you have created', expect: 'Quick create a new vector store', hint: { en: 'The team has no vector store yet. Let Bedrock create one.', he: 'לצוות עדיין אין vector store. תן ל-Bedrock ליצור אחד.' } },
              { label: 'Vector store', type: 'select', options: ['Amazon OpenSearch Serverless', 'Amazon Aurora PostgreSQL Serverless', 'Amazon Neptune Analytics', 'Amazon S3 Vectors'], value: 'Amazon OpenSearch Serverless', expect: 'Amazon S3 Vectors', n: 4, hint: { en: 'Low traffic, tight budget, no hybrid search needed.', he: 'תעבורה נמוכה, תקציב הדוק, אין צורך ב-hybrid search.' } } ] }
          ],
          buttons: ['Previous', 'Next'],
          callouts: [ { n: 1, en: 'The embedding model turns each chunk into a vector. It cannot be changed after the knowledge base is created.', he: 'מודל ה-embedding הופך כל chunk לוקטור. אי אפשר לשנות אותו אחרי שה-knowledge base נוצר.' }, { n: 2, en: 'Titan V2 offers 256, 512 or 1024. The vector index is created for exactly this size.', he: 'Titan V2 מציע 256, 512 או 1024. ה-vector index נוצר בדיוק לגודל הזה.' }, { n: 3, en: 'Quick create exists only in the console. With the API you create the store yourself and pass its details.', he: 'Quick create קיים רק ב-console. עם ה-API יוצרים את ה-store לבד ומעבירים את הפרטים שלו.' }, { n: 4, en: 'Four quick-create choices. S3 Vectors is the low-cost one; OpenSearch Serverless is the one with hybrid search; Neptune Analytics is for GraphRAG.', he: 'ארבע אפשרויות quick-create. S3 Vectors היא הזולה; OpenSearch Serverless היא זו עם hybrid search; Neptune Analytics מיועדת ל-GraphRAG.' } ],
          success: { en: 'Right. Titan V2 at 1024 dimensions on S3 Vectors: no always-on cluster. If the team later needs hybrid search, they will have to move to a store that supports it and re-ingest.', he: 'נכון. Titan V2 ב-1024 ממדים על S3 Vectors: אין cluster שתמיד דולק. אם הצוות יצטרך hybrid search בהמשך, הוא יצטרך לעבור ל-store שתומך בזה ולעשות ingestion מחדש.' },
          caption: { en: 'Simplified: one step of the customer-managed knowledge base wizard. The panel names and the choices come from the docs; the page title and the radio label are simplified.', he: 'מפושט: שלב אחד מתוך ה-wizard של knowledge base מסוג customer-managed. שמות הפאנלים והאפשרויות מהתיעוד; כותרת הדף ותווית ה-radio מפושטות.' } },
        { t: 'h', en: 'PartyRock', he: 'PartyRock' },
        { t: 'p', en: '[[PartyRock]] (partyrock.aws) is a free, no-code website for building small GenAI apps on Bedrock models. It is for learning and for showing an idea to a non-technical colleague in ten minutes. It is not a place for production apps or private data.', he: '[[PartyRock]] (partyrock.aws) הוא אתר חינמי, בלי קוד, לבניית אפליקציות GenAI קטנות על מודלים של Bedrock. הוא מיועד ללמידה ולהצגת רעיון לעמית לא טכני בעשר דקות. זה לא מקום לאפליקציות פרודקשן או למידע פרטי.' },
        { t: 'match', prompt: { en: 'Match the service to its one-line job.', he: 'התאם את השירות לתפקיד שלו בשורה אחת.' }, pairs: [
          { a: 'Nova 2 Lite', b: { en: 'Reasoning chat model with a 1M-token context', he: 'מודל צ׳אט עם reasoning ו-context של מיליון טוקנים' } },
          { a: 'Titan Text Embeddings V2', b: { en: 'Text in, a vector of 256 / 512 / 1024 numbers out', he: 'טקסט נכנס, וקטור של 256 / 512 / 1024 מספרים יוצא' } },
          { a: 'Bedrock Data Automation', b: { en: 'Files in, structured fields with confidence out', he: 'קבצים נכנסים, שדות מובנים עם confidence יוצאים' } },
          { a: 'S3 Vectors', b: { en: 'Cheap storage and search for vectors', he: 'אחסון וחיפוש זולים לוקטורים' } },
          { a: 'Nova Act', b: { en: 'Agents that click through web pages', he: 'סוכנים שלוחצים בדפי web' } },
          { a: 'PartyRock', b: { en: 'Free no-code playground for demos', he: 'Playground חינמי בלי קוד לדמואים' } }
        ] },
        { t: 'reveal', q: { en: 'A colleague says: "We put 50 million vectors in OpenSearch Serverless and the bill hurts. Should we move to S3 Vectors?" What do you ask before answering?', he: 'עמית אומר: "שמנו 50 מיליון וקטורים ב-OpenSearch Serverless והחשבון כואב. לעבור ל-S3 Vectors?" מה אתה שואל לפני שאתה עונה?' },
          a: { en: 'Three questions. (1) Do you use hybrid search or filters like startsWith / stringContains? In a Knowledge Base, S3 Vectors does not support them. (2) How much metadata per chunk? With a Knowledge Base, S3 Vectors allows 1 KB of custom metadata and 35 keys per vector. (3) What latency do users accept? S3 Vectors is the cheap tier, not the fastest one. If the workload is "many vectors, few queries, simple filters", moving saves real money. A middle path also exists: S3 Vectors integrates with OpenSearch Service for tiering, so cold data can sit in S3 Vectors.', he: 'שלוש שאלות. (1) האם משתמשים ב-hybrid search או בפילטרים כמו startsWith / stringContains? ב-Knowledge Base, S3 Vectors לא תומך בהם. (2) כמה metadata יש לכל chunk? עם Knowledge Base, S3 Vectors מאפשר 1 KB של metadata מותאם ו-35 keys לוקטור. (3) איזה latency המשתמשים מקבלים? S3 Vectors הוא השכבה הזולה, לא המהירה ביותר. אם העומס הוא "הרבה וקטורים, מעט שאילתות, פילטרים פשוטים", המעבר חוסך כסף אמיתי. יש גם דרך ביניים: S3 Vectors משתלב עם OpenSearch Service ל-tiering, כך שמידע קר יכול לשבת ב-S3 Vectors.' } }
      ]
    },
    {
      id: 'm14l4', minutes: 12,
      title: { en: 'The classic AI services: when not to use an LLM', he: 'שירותי ה-AI הקלאסיים: מתי לא להשתמש ב-LLM' },
      blocks: [
        { t: 'p', en: 'Before [[GenAI]], AWS already sold AI as small, single-purpose APIs. They are still here, and a pro reaches for them often. An [[LLM]] can do almost anything, but "can" is not "should": for a narrow job at high volume, a purpose-built API is usually cheaper, faster and more predictable.', he: 'לפני [[GenAI]], AWS כבר מכרה AI בתור APIs קטנים למטרה אחת. הם עדיין כאן, ומקצוען משתמש בהם הרבה. [[LLM]] יכול לעשות כמעט הכול, אבל "יכול" זה לא "צריך": למשימה צרה בנפח גבוה, API ייעודי בדרך כלל זול יותר, מהיר יותר וצפוי יותר.' },
        { t: 'table', head: { en: ['Service', 'One line', 'You pay per'], he: ['שירות', 'בשורה אחת', 'משלמים לפי'] }, rows: {
          en: [['Amazon Comprehend', 'Text analysis: entities, sentiment, key phrases, PII detection, custom classification.', 'unit of text'], ['Amazon Textract', '[[OCR]] plus forms, tables, queries, expense and ID analysis.', 'page'], ['Amazon Transcribe', 'Speech to text, batch and streaming, call analytics.', 'second of audio'], ['Amazon Polly', 'Text to speech in many voices.', 'character'], ['Amazon Rekognition', 'Image and video analysis: labels, faces, moderation, text in images.', 'see the pricing page'], ['Amazon Translate', 'Machine translation, real-time and batch, with custom terminology.', 'character'], ['Amazon Lex', 'Builder for chatbots and voice bots based on intents and slots.', 'see the pricing page'], ['Amazon Personalize', 'Managed recommendations ("customers like you also bought").', 'see the pricing page']],
          he: [['Amazon Comprehend', 'ניתוח טקסט: entities, sentiment, key phrases, זיהוי PII, סיווג מותאם.', 'יחידת טקסט'], ['Amazon Textract', '[[OCR]] ועוד טפסים, טבלאות, queries, ניתוח הוצאות ותעודות.', 'דף'], ['Amazon Transcribe', 'דיבור לטקסט, batch ו-streaming, ניתוח שיחות.', 'שנייה של אודיו'], ['Amazon Polly', 'טקסט לדיבור בהרבה קולות.', 'תו'], ['Amazon Rekognition', 'ניתוח תמונות ווידאו: labels, פנים, moderation, טקסט בתמונות.', 'ראה דף התמחור'], ['Amazon Translate', 'תרגום מכונה, real-time ו-batch, עם custom terminology.', 'תו'], ['Amazon Lex', 'בונה צ׳אטבוטים ובוטים קוליים על בסיס intents ו-slots.', 'ראה דף התמחור'], ['Amazon Personalize', 'המלצות מנוהלות ("לקוחות כמוך קנו גם").', 'ראה דף התמחור']] } },
        { t: 'note', kind: 'jargon', en: 'Lex words: an **intent** is what the user wants ("book a room"). A **slot** is a detail the bot must collect ("which date?"). A Lex bot follows a designed dialog; it does not improvise. Bedrock Flows even has a Lex node, so the two worlds can be combined.', he: 'מילים של Lex: **intent** הוא מה שהמשתמש רוצה ("להזמין חדר"). **slot** הוא פרט שהבוט חייב לאסוף ("לאיזה תאריך?"). בוט של Lex הולך לפי דיאלוג מתוכנן; הוא לא מאלתר. ב-Bedrock Flows יש אפילו node של Lex, כך שאפשר לשלב בין שני העולמות.' },
        { t: 'h', en: 'The decision rule', he: 'כלל ההחלטה' },
        { t: 'table', head: { en: ['Use the classic service when…', 'Use an LLM when…'], he: ['משתמשים בשירות הקלאסי כש…', 'משתמשים ב-LLM כש…'] }, rows: {
          en: [['The task is narrow and always the same (transcribe, translate, read a form).', 'The task needs reasoning, or the instructions change from case to case.'], ['Volume is high and cost per item matters.', 'Volume is low or each item is worth a lot.'], ['You need the same input to give the same output, with a confidence score.', 'Some variation is fine and you check quality with evaluations.'], ['The input is not text at all (audio, image) and must first become text.', 'The input is already text, or the model is multimodal and the volume is small.'], ['Low latency in a real-time pipeline.', 'A second or more of delay is acceptable.']],
          he: [['המשימה צרה ותמיד זהה (תמלול, תרגום, קריאת טופס).', 'המשימה דורשת reasoning, או שההוראות משתנות ממקרה למקרה.'], ['הנפח גבוה והעלות לפריט חשובה.', 'הנפח נמוך או שכל פריט שווה הרבה.'], ['צריך שאותו קלט ייתן אותו פלט, עם confidence score.', 'קצת שונות זה בסדר ובודקים איכות עם evaluations.'], ['הקלט הוא בכלל לא טקסט (אודיו, תמונה) וחייב קודם להפוך לטקסט.', 'הקלט כבר טקסט, או שהמודל multimodal והנפח קטן.'], ['Latency נמוך ב-pipeline בזמן אמת.', 'שנייה או יותר של השהיה מקובלת.']] } },
        { t: 'note', kind: 'tip', en: 'In real systems the answer is usually **both**. The classic service does the mechanical step and the LLM does the thinking step. A call-center pipeline: Transcribe turns the call into text → an LLM on Bedrock summarizes it and decides the next action → Polly reads the answer to the caller.', he: 'במערכות אמיתיות התשובה היא בדרך כלל **שניהם**. השירות הקלאסי עושה את השלב המכני וה-LLM עושה את שלב החשיבה. pipeline של מוקד שירות: Transcribe הופך את השיחה לטקסט ← LLM ב-Bedrock מסכם אותה ומחליט על הפעולה הבאה ← Polly מקריא את התשובה למתקשר.' },
        { t: 'flow', steps: { en: ['Caller speaks', 'Transcribe: audio → text', 'Bedrock model: understand + decide', 'Polly: text → audio', 'Caller hears the answer'], he: ['המתקשר מדבר', 'Transcribe: אודיו ← טקסט', 'מודל ב-Bedrock: להבין + להחליט', 'Polly: טקסט ← אודיו', 'המתקשר שומע את התשובה'] }, caption: { en: 'Three hops. A speech-to-speech model such as Nova 2 Sonic does it in one hop, with less delay but less control over each step.', he: 'שלוש קפיצות. מודל דיבור-לדיבור כמו Nova 2 Sonic עושה את זה בקפיצה אחת, עם פחות השהיה אבל פחות שליטה בכל שלב.' } },
        { t: 'quiz', q: { en: 'A marketplace must translate 5 million short product titles per day into 6 languages. The titles are simple and the cost per title must be tiny. What do you choose first?', he: 'מרקטפלייס צריך לתרגם 5 מיליון כותרות מוצר קצרות ביום ל-6 שפות. הכותרות פשוטות והעלות לכותרת חייבת להיות זעירה. מה בוחרים קודם?' },
          options: { en: ['The strongest Claude model, to get the best translation', 'A fine-tuned model on SageMaker AI', 'A Knowledge Base with the titles in all languages', 'Amazon Translate, with custom terminology for brand names'], he: ['המודל החזק ביותר של Claude, כדי לקבל את התרגום הטוב ביותר', 'מודל אחרי fine-tuning ב-SageMaker AI', 'Knowledge Base עם הכותרות בכל השפות', 'Amazon Translate, עם custom terminology לשמות מותגים'] },
          answer: 3, explain: { en: 'Narrow task, huge volume, simple text: a per-character translation API is the cheap, fast and predictable choice, and custom terminology keeps brand names fixed. An LLM earns its price when the text needs tone, context or rewriting, for example marketing copy.', he: 'משימה צרה, נפח ענק, טקסט פשוט: API תרגום שמחויב לפי תו הוא הבחירה הזולה, המהירה והצפויה, ו-custom terminology שומר על שמות מותגים. LLM מצדיק את המחיר כשהטקסט דורש טון, הקשר או ניסוח מחדש, למשל טקסט שיווקי.' } },
        { t: 'quiz', q: { en: 'Support tickets arrive as free text. For each ticket the team wants: is the customer angry, and a two-sentence summary that follows the team\'s own writing rules. Which split is the most sensible?', he: 'טיקטים של תמיכה מגיעים כטקסט חופשי. לכל טיקט הצוות רוצה: האם הלקוח כועס, וסיכום בשני משפטים שמתאים לכללי הכתיבה של הצוות. איזו חלוקה הכי הגיונית?' },
          options: { en: ['One LLM call that returns both the sentiment label and the summary as structured output', 'Rekognition for sentiment, Polly for the summary', 'Textract for sentiment, Translate for the summary', 'Lex for both'], he: ['קריאת LLM אחת שמחזירה גם את תווית ה-sentiment וגם את הסיכום כ-structured output', 'Rekognition ל-sentiment, Polly לסיכום', 'Textract ל-sentiment, Translate לסיכום', 'Lex לשניהם'] },
          answer: 0, explain: { en: 'The summary with house rules needs an LLM anyway, so adding the sentiment label to the same structured output costs almost nothing extra. Comprehend sentiment would be the right call if you needed only the label at very high volume. The other options use services for jobs they do not do: Rekognition is for images, Textract for documents, Polly for speech.', he: 'הסיכום עם כללי הבית דורש LLM בכל מקרה, אז הוספת תווית ה-sentiment לאותו structured output כמעט לא עולה יותר. sentiment של Comprehend היה הבחירה הנכונה אם היית צריך רק את התווית בנפח גבוה מאוד. שאר האפשרויות משתמשות בשירותים למשימות שהם לא עושים: Rekognition לתמונות, Textract למסמכים, Polly לדיבור.' } },
        { t: 'h', en: 'Documents: Textract, BDA, or a model?', he: 'מסמכים: Textract, BDA, או מודל?' },
        { t: 'p', en: 'Three tools can read a scanned page, and people mix them up. Textract is the classic [[OCR]] and forms API. [[Bedrock Data Automation]] is the newer GenAI-era service with blueprints and also audio and video. A multimodal foundation model can read a page too, and it is the most flexible and the least predictable. A fair rule: a fixed schema at volume → BDA or Textract; a one-off question about an unusual document → a model.', he: 'שלושה כלים יכולים לקרוא דף סרוק, ואנשים מבלבלים ביניהם. Textract הוא ה-API הקלאסי ל-[[OCR]] ולטפסים. [[Bedrock Data Automation]] הוא השירות החדש יותר מעידן ה-GenAI, עם blueprints וגם אודיו ווידאו. גם foundation model מולטימודלי יכול לקרוא דף, והוא הכי גמיש והכי פחות צפוי. כלל הוגן: סכמה קבועה בנפח ← BDA או Textract; שאלה חד-פעמית על מסמך לא רגיל ← מודל.' },
        { t: 'h', en: 'Status notes for the classic family', he: 'הערות סטטוס למשפחה הקלאסית' },
        { t: 'list', en: ['[[Kendra]] (enterprise search) is in [[Maintenance]] since 2026-06-30 and closed to new customers from 2026-07-30. AWS says to use a **Bedrock Managed Knowledge Base** instead: managed vector store, built-in connectors, always-hybrid search, and an agentic retrieval API.', 'Comprehend is active, but three of its features are in maintenance (2026-03-31): Topic Modeling, Event Detection and Prompt Safety Classification. For prompt safety, the current tool is the prompt attack filter in Bedrock Guardrails.', 'Rekognition is active, but Streaming Events and Batch Image Content Moderation are in maintenance, and Person Pathing was shut down.', 'Also gone or going: Amazon Lookout for Equipment / Metrics / Vision (shut down), Amazon Forecast, Amazon Fraud Detector and CodeGuru Reviewer (maintenance), DevOps Guru (sunset, ends 2027-09-29).', 'Textract, Transcribe, Polly, Translate, Lex and Personalize are on none of the lifecycle lists.'], he: ['[[Kendra]] (חיפוש ארגוני) ב-[[Maintenance]] מאז 2026-06-30 וסגור ללקוחות חדשים מ-2026-07-30. AWS אומרת להשתמש במקומו ב-**Bedrock Managed Knowledge Base**: vector store מנוהל, connectors מובנים, חיפוש hybrid תמיד, ו-API של agentic retrieval.', 'Comprehend פעיל, אבל שלוש יכולות שלו ב-maintenance (2026-03-31): Topic Modeling, Event Detection ו-Prompt Safety Classification. לבטיחות פרומפטים, הכלי העדכני הוא פילטר ה-prompt attack ב-Bedrock Guardrails.', 'Rekognition פעיל, אבל Streaming Events ו-Batch Image Content Moderation ב-maintenance, ו-Person Pathing נסגר.', 'גם נעלמו או בדרך החוצה: Amazon Lookout for Equipment / Metrics / Vision (נסגרו), Amazon Forecast, Amazon Fraud Detector ו-CodeGuru Reviewer (maintenance), DevOps Guru (sunset, מסתיים ב-2027-09-29).', 'Textract, Transcribe, Polly, Translate, Lex ו-Personalize לא מופיעים באף אחת מרשימות מחזור-החיים.'] },
        { t: 'match', prompt: { en: 'Use this instead of an LLM when… Match the situation to the service.', he: 'משתמשים בזה במקום LLM כש… התאם את המצב לשירות.' }, pairs: [
          { a: { en: '10,000 hours of recorded calls must become text', he: '10,000 שעות של שיחות מוקלטות צריכות להפוך לטקסט' }, b: 'Amazon Transcribe' },
          { a: { en: 'An app must read articles aloud', he: 'אפליקציה צריכה להקריא מאמרים בקול' }, b: 'Amazon Polly' },
          { a: { en: 'User-uploaded photos must be checked for unsafe content', he: 'תמונות שמשתמשים מעלים צריכות בדיקה לתוכן לא בטוח' }, b: 'Amazon Rekognition' },
          { a: { en: 'Tables and key-value pairs from scanned tax forms', he: 'טבלאות וזוגות key-value מטופסי מס סרוקים' }, b: 'Amazon Textract' },
          { a: { en: 'Find and count PII entities in millions of log lines', he: 'למצוא ולספור ישויות PII במיליוני שורות לוג' }, b: 'Amazon Comprehend' },
          { a: { en: 'A phone menu that must follow one exact, approved dialog', he: 'תפריט טלפוני שחייב ללכת לפי דיאלוג אחד מדויק ומאושר' }, b: 'Amazon Lex' }
        ] },
        { t: 'quiz', q: { en: 'A bank wants a voice bot for "block my card". Compliance demands that the bot asks exactly three fixed questions in a fixed order, and never says anything that was not approved. What is the best core?', he: 'בנק רוצה בוט קולי ל-"חסום את הכרטיס שלי". ה-compliance דורש שהבוט ישאל בדיוק שלוש שאלות קבועות בסדר קבוע, ולעולם לא יגיד משהו שלא אושר. מה הליבה הכי טובה?' },
          options: { en: ['A free-form LLM agent with a long system prompt', 'Nova 2 Sonic with temperature 0', 'Amazon Lex with one intent and three slots', 'Amazon Kendra'], he: ['סוכן LLM חופשי עם system prompt ארוך', 'Nova 2 Sonic עם temperature 0', 'Amazon Lex עם intent אחד ושלושה slots', 'Amazon Kendra'] },
          answer: 2, explain: { en: 'A fixed, auditable dialog is what intents and slots were made for: the bot can only say the prompts you wrote. An LLM, even at low temperature, is non-deterministic and can be talked into saying something else. You can still call an LLM from the bot for one free-text step if you need it.', he: 'דיאלוג קבוע שאפשר לבקר הוא בדיוק מה ש-intents ו-slots נועדו לו: הבוט יכול להגיד רק את הניסוחים שכתבת. LLM, גם ב-temperature נמוכה, הוא non-deterministic ואפשר לשכנע אותו להגיד משהו אחר. עדיין אפשר לקרוא ל-LLM מתוך הבוט לשלב אחד של טקסט חופשי אם צריך.' } },
        { t: 'quiz', q: { en: 'A new project needs "search over 200,000 company documents with answers and citations". An architect proposes Amazon Kendra because "that is what it is for". The company has never used Kendra. What is wrong?', he: 'פרויקט חדש צריך "חיפוש על 200,000 מסמכי חברה עם תשובות וציטוטים". ארכיטקט מציע Amazon Kendra כי "בשביל זה הוא קיים". החברה מעולם לא השתמשה ב-Kendra. מה לא בסדר?' },
          options: { en: ['Nothing, Kendra is the recommended service', 'Kendra is closed to new customers since 2026-07-30; use a Bedrock Managed Knowledge Base', 'Kendra cannot index more than 10,000 documents', 'Kendra only works with Amazon Q Developer'], he: ['שום דבר, Kendra הוא השירות המומלץ', 'Kendra סגור ללקוחות חדשים מ-2026-07-30; משתמשים ב-Bedrock Managed Knowledge Base', 'Kendra לא יכול לאנדקס יותר מ-10,000 מסמכים', 'Kendra עובד רק עם Amazon Q Developer'] },
          answer: 1, explain: { en: 'Kendra went into maintenance on 2026-06-30 and new customers cannot start with it. AWS names the Bedrock Managed Knowledge Base as the replacement. The design idea was right, the product name is two years old.', he: 'Kendra נכנס ל-maintenance ב-2026-06-30 ולקוחות חדשים לא יכולים להתחיל איתו. AWS מציינת את Bedrock Managed Knowledge Base כמחליף. רעיון התכנון נכון, שם המוצר בן שנתיים.' } },
        { t: 'reveal', q: { en: 'Interview: "Why would I pay for Textract or Transcribe when my multimodal LLM can read images and my speech model can hear?"', he: 'ראיון: "למה שאשלם על Textract או Transcribe כשה-LLM המולטימודלי שלי קורא תמונות ומודל הדיבור שלי שומע?"' },
          a: { en: 'Because of four things: cost, speed, predictability and evidence. A purpose-built API is priced per page or per second and is usually much cheaper at volume. It is faster because it does one thing. It gives the same result for the same input, with confidence scores and positions on the page, which auditors and human reviewers need. And it has no prompt to attack. I would use the LLM where judgment is needed, on the text that the classic service produced. If volume is small and the documents are all different, going straight to the model is a fair shortcut.', he: 'בגלל ארבעה דברים: עלות, מהירות, צפיות וראיות. API ייעודי מתומחר לדף או לשנייה ובדרך כלל זול בהרבה בנפח. הוא מהיר יותר כי הוא עושה דבר אחד. הוא נותן אותה תוצאה לאותו קלט, עם confidence scores ומיקומים על הדף, שמבקרים ובודקים אנושיים צריכים. ואין לו פרומפט שאפשר לתקוף. הייתי משתמש ב-LLM איפה שצריך שיקול דעת, על הטקסט שהשירות הקלאסי הפיק. אם הנפח קטן והמסמכים כולם שונים, ללכת ישר למודל זה קיצור דרך הוגן.' } }
      ]
    },
    {
      id: 'm14l5', minutes: 13,
      title: { en: 'Certifications, a study plan, and staying up to date', he: 'הסמכות, תוכנית לימוד, ואיך נשארים מעודכנים' },
      blocks: [
        { t: 'p', en: 'A certificate does not make you a pro, but it gives your knowledge a shape that employers recognize, and the exam guide is a free checklist of what AWS thinks a GenAI developer must know. Three exams matter for you.', he: 'תעודה לא הופכת אותך למקצוען, אבל היא נותנת לידע שלך צורה שמעסיקים מזהים, ומדריך המבחן הוא רשימת בדיקה חינמית של מה ש-AWS חושבת שמפתח GenAI חייב לדעת. שלושה מבחנים חשובים בשבילך.' },
        { t: 'table', head: { en: ['Exam', 'Level', 'Format', 'What it tests'], he: ['מבחן', 'רמה', 'פורמט', 'מה הוא בודק'] }, rows: {
          en: [['**AI Practitioner** ([[AIF-C01]])', 'Foundational', '65 questions (50 scored), 90 minutes, pass 700/1000, 100 USD', 'Concepts and vocabulary: what AI, ML and GenAI are, when to use foundation models, responsible AI, security basics. No code.'], ['**Generative AI Developer - Professional** ([[AIP-C01]])', 'Professional', '75 questions (65 scored), 180 minutes, pass 750/1000, 300 USD', 'Building and running production GenAI apps on AWS: model integration, RAG, agents, safety, cost, testing. Long scenario questions.'], ['**ML Engineer - Associate** ([[MLA-C02]])', 'Associate', 'New version in beta since 2026-09-29 (85 questions, 170 minutes, 75 USD). Standard format per the guide: 50 scored + 15 unscored, pass 720.', 'The ML lifecycle on SageMaker AI: data preparation, training, deployment, monitoring. C02 adds a lot of GenAI.']],
          he: [['**AI Practitioner** ([[AIF-C01]])', 'Foundational', '65 שאלות (50 נספרות), 90 דקות, ציון עובר 700/1000, 100 דולר', 'מושגים ואוצר מילים: מה זה AI, ML ו-GenAI, מתי להשתמש ב-foundation models, responsible AI, יסודות אבטחה. בלי קוד.'], ['**Generative AI Developer - Professional** ([[AIP-C01]])', 'Professional', '75 שאלות (65 נספרות), 180 דקות, ציון עובר 750/1000, 300 דולר', 'בנייה והפעלה של אפליקציות GenAI בפרודקשן על AWS: שילוב מודלים, RAG, סוכנים, בטיחות, עלות, בדיקות. שאלות תרחיש ארוכות.'], ['**ML Engineer - Associate** ([[MLA-C02]])', 'Associate', 'גרסה חדשה בבטא מ-2026-09-29 (85 שאלות, 170 דקות, 75 דולר). הפורמט הרגיל לפי המדריך: 50 נספרות + 15 לא נספרות, ציון עובר 720.', 'מחזור החיים של ML על SageMaker AI: הכנת דאטה, אימון, פריסה, ניטור. C02 מוסיף הרבה GenAI.']] } },
        { t: 'note', kind: 'info', en: 'Version status, November 2026. **AIF-C01** is the current version; no C02 is announced. **AIP-C01** is the standard (non-beta) exam and it was refreshed to include AgentCore. **MLA**: the English C01 exam ended on 2026-09-28; C02 is in beta and its general availability date is still "TBD". The old **Machine Learning - Specialty (MLS-C01)** is retired: its last day was 2026-03-31. There is also **AWS Agentic AI Demonstrated**, a hands-on *microcredential* (not a full certification) done in a live AWS environment.', he: 'סטטוס גרסאות, נובמבר 2026. **AIF-C01** היא הגרסה הנוכחית; לא הוכרז C02. **AIP-C01** הוא המבחן הרגיל (לא בטא) והוא עודכן כדי לכלול את AgentCore. **MLA**: מבחן C01 באנגלית הסתיים ב-2026-09-28; C02 בבטא ותאריך הזמינות הכללית שלו עדיין "TBD". ה-**Machine Learning - Specialty (MLS-C01)** הישן יצא לפנסיה: היום האחרון שלו היה 2026-03-31. יש גם **AWS Agentic AI Demonstrated**, *microcredential* מעשי (לא הסמכה מלאה) שנעשה בסביבת AWS חיה.' },
        { t: 'quiz', q: { en: 'A product manager with no coding background wants to speak the language of the GenAI team and prove it. Which exam do you point them to?', he: 'מנהלת מוצר בלי רקע בקוד רוצה לדבר בשפה של צוות ה-GenAI ולהוכיח את זה. לאיזה מבחן תפנה אותה?' },
          options: { en: ['Generative AI Developer - Professional', 'ML Engineer - Associate', 'Machine Learning - Specialty', 'AI Practitioner'], he: ['Generative AI Developer - Professional', 'ML Engineer - Associate', 'Machine Learning - Specialty', 'AI Practitioner'] },
          answer: 3, explain: { en: 'AI Practitioner is Foundational: concepts, use cases, responsible AI and security basics, with no code. The Professional exam expects two or more years of building production applications. The ML Specialty exam no longer exists (retired 2026-03-31).', he: 'AI Practitioner הוא ברמת Foundational: מושגים, מקרי שימוש, responsible AI ויסודות אבטחה, בלי קוד. המבחן ה-Professional מצפה לשנתיים או יותר של בניית אפליקציות פרודקשן. מבחן ה-ML Specialty כבר לא קיים (יצא לפנסיה ב-2026-03-31).' } },
        { t: 'h', en: 'AIP-C01: the exam that matches this course', he: 'AIP-C01: המבחן שמתאים לקורס הזה' },
        { t: 'p', en: 'AWS describes the target candidate as someone with two or more years of building production applications on AWS or with open source, plus one year of hands-on GenAI. Model training, advanced ML and feature engineering are **out of scope**: this is a developer exam, not a data-science exam. The questions are multiple choice and multiple response.', he: 'AWS מתארת את המועמד כמי שיש לו שנתיים או יותר של בניית אפליקציות פרודקשן על AWS או עם קוד פתוח, ועוד שנה של GenAI מעשי. אימון מודלים, ML מתקדם ו-feature engineering הם **מחוץ לתחום**: זה מבחן למפתחים, לא מבחן data science. השאלות הן בחירה מרובה ותשובות מרובות.' },
        { t: 'table', head: { en: ['AIP-C01 domain', 'Weight', 'Course modules that prepare you (our mapping)'], he: ['תחום ב-AIP-C01', 'משקל', 'מודולים בקורס שמכינים אותך (המיפוי שלנו)'] }, rows: {
          en: [['1. Foundation Model Integration, Data Management, and Compliance', '31%', 'm01 foundations · m03 Bedrock APIs and inference options · m04 prompts and structured output · m05 RAG and Knowledge Bases · m14 other services'], ['2. Implementation and Integration', '26%', 'm04 tool use · m06 agents, Strands, MCP, A2A · m07 Runtime · m08 Gateway and built-in tools · m09 Memory · m02 Lambda, S3 and friends'], ['3. AI Safety, Security, and Governance', '20%', 'm10 Guardrails and Policy · m13 security · m08 Identity · m02 IAM and KMS'], ['4. Operational Efficiency and Optimization for GenAI Applications', '12%', 'm03 caching, tiers, quotas · m13 cost and production · m12 observability'], ['5. Testing, Validation, and Troubleshooting', '11%', 'm11 evaluations · m12 traces and debugging · m15 capstone incidents']],
          he: [['1. Foundation Model Integration, Data Management, and Compliance', '31%', 'm01 יסודות · m03 ה-APIs של Bedrock ואפשרויות inference · m04 פרומפטים ו-structured output · m05 RAG ו-Knowledge Bases · m14 שירותים נוספים'], ['2. Implementation and Integration', '26%', 'm04 tool use · m06 סוכנים, Strands, MCP, A2A · m07 Runtime · m08 Gateway וכלים מובנים · m09 Memory · m02 Lambda, S3 וחברים'], ['3. AI Safety, Security, and Governance', '20%', 'm10 Guardrails ו-Policy · m13 אבטחה · m08 Identity · m02 IAM ו-KMS'], ['4. Operational Efficiency and Optimization for GenAI Applications', '12%', 'm03 caching, tiers, quotas · m13 עלות ופרודקשן · m12 observability'], ['5. Testing, Validation, and Troubleshooting', '11%', 'm11 evaluations · m12 traces ודיבוג · m15 תקריות הקפסטון']] } },
        { t: 'note', kind: 'warn', en: 'The official list of in-scope services lags behind reality. It names Amazon Bedrock AgentCore, Kiro and Amazon Quick, but it **also** still names services that are now in maintenance or sunset: Amazon Q Developer, Amazon Q Business, Kendra, SageMaker Clarify, Model Monitor, Ground Truth and Augmented AI. So for the exam, know what each of those did. For real work, know what replaced them. It also lists many non-AI services: Lambda, Step Functions, EventBridge, SQS, API Gateway, OpenSearch Service, DynamoDB, Cognito, KMS, Secrets Manager, CloudWatch, X-Ray, CloudTrail, PrivateLink.', he: 'הרשימה הרשמית של השירותים במבחן מפגרת אחרי המציאות. היא כוללת את Amazon Bedrock AgentCore, Kiro ו-Amazon Quick, אבל **גם** עדיין כוללת שירותים שעכשיו ב-maintenance או ב-sunset: Amazon Q Developer, Amazon Q Business, Kendra, SageMaker Clarify, Model Monitor, Ground Truth ו-Augmented AI. אז למבחן, צריך לדעת מה כל אחד מהם עשה. לעבודה אמיתית, צריך לדעת מה החליף אותם. היא כוללת גם הרבה שירותים שאינם AI: Lambda, Step Functions, EventBridge, SQS, API Gateway, OpenSearch Service, DynamoDB, Cognito, KMS, Secrets Manager, CloudWatch, X-Ray, CloudTrail, PrivateLink.' },
        { t: 'quiz', q: { en: 'You have four weeks before AIP-C01 and can study one domain deeply per week, with one week of mixed practice. Which two domains deserve the deepest weeks, based on weight?', he: 'יש לך ארבעה שבועות לפני AIP-C01 ואתה יכול ללמוד לעומק תחום אחד בשבוע, עם שבוע אחד של תרגול מעורב. אילו שני תחומים מגיע להם השבועות העמוקים ביותר, לפי המשקל?' },
          options: { en: ['Domain 1 (model integration, data, compliance) and Domain 2 (implementation and integration)', 'Domain 4 (optimization) and Domain 5 (testing)', 'Domain 3 (safety) and Domain 5 (testing)', 'Domain 5 (testing) only, it is the hardest'], he: ['תחום 1 (שילוב מודלים, דאטה, compliance) ותחום 2 (מימוש ואינטגרציה)', 'תחום 4 (אופטימיזציה) ותחום 5 (בדיקות)', 'תחום 3 (בטיחות) ותחום 5 (בדיקות)', 'רק תחום 5 (בדיקות), הוא הקשה ביותר'] },
          answer: 0, explain: { en: 'Domains 1 and 2 are 31% + 26% = 57% of the scored questions. Safety is 20%, optimization 12% and testing 11%. Study by weight first, then by your own weak spots. Do not skip the small domains: 23% together is the difference between pass and fail at 750.', he: 'תחומים 1 ו-2 הם 31% + 26% = 57% מהשאלות הנספרות. בטיחות 20%, אופטימיזציה 12% ובדיקות 11%. לומדים קודם לפי משקל, ואחר כך לפי נקודות החולשה שלך. לא מדלגים על התחומים הקטנים: 23% יחד הם ההבדל בין עובר לנכשל ב-750.' } },
        { t: 'h', en: 'The other two, in short', he: 'שני האחרים, בקצרה' },
        { t: 'table', head: { en: ['Exam', 'Domains and weights'], he: ['מבחן', 'תחומים ומשקלים'] }, rows: {
          en: [['AIF-C01', 'Fundamentals of AI and ML 20% · Fundamentals of GenAI 24% · Applications of Foundation Models 28% · Guidelines for Responsible AI 14% · Security, Compliance, and Governance for AI Solutions 14%'], ['MLA-C02', 'Data Preparation for ML and AI 28% · ML Model and Foundation Model Development 24% · Deployment and Orchestration of ML and AI Workflows 24% · Operating, Monitoring, and Securing ML and AI Solutions 24%']],
          he: [['AIF-C01', 'Fundamentals of AI and ML 20% · Fundamentals of GenAI 24% · Applications of Foundation Models 28% · Guidelines for Responsible AI 14% · Security, Compliance, and Governance for AI Solutions 14%'], ['MLA-C02', 'Data Preparation for ML and AI 28% · ML Model and Foundation Model Development 24% · Deployment and Orchestration of ML and AI Workflows 24% · Operating, Monitoring, and Securing ML and AI Solutions 24%']] } },
        { t: 'p', en: 'MLA-C02 is interesting for you because it moved toward GenAI: it adds vector databases, embeddings, RAG document preparation and chunking, model selection and fine-tuning, Bedrock Knowledge Bases, agents, Prompt Management, Bedrock evaluations, Guardrails and token cost monitoring. After this course about half of it is familiar; the other half is classic SageMaker AI work from lesson 1.', he: 'MLA-C02 מעניין בשבילך כי הוא זז לכיוון GenAI: הוא מוסיף vector databases, embeddings, הכנת מסמכים ל-RAG ו-chunking, בחירת מודל ו-fine-tuning, Bedrock Knowledge Bases, סוכנים, Prompt Management, evaluations של Bedrock, Guardrails וניטור עלות טוקנים. אחרי הקורס הזה בערך חצי ממנו מוכר; החצי השני הוא עבודת SageMaker AI קלאסית משיעור 1.' },
        { t: 'h', en: 'A study plan that works', he: 'תוכנית לימוד שעובדת' },
        { t: 'order', prompt: { en: 'Put the steps of a sensible AIP-C01 preparation in order.', he: 'סדר את השלבים של הכנה הגיונית ל-AIP-C01.' }, items: { en: ['Read the official exam guide and the in-scope services list', 'Finish this course and its final exam; note every weak topic', 'Build the capstone (module 15) in a real AWS account', 'Review weak topics in the AWS docs, by domain weight', 'Take timed practice sets: about 2.4 minutes per question', 'Book the exam, and re-check What\'s New the week before'], he: ['לקרוא את מדריך המבחן הרשמי ואת רשימת השירותים שבתחום', 'לסיים את הקורס הזה ואת המבחן המסכם; לרשום כל נושא חלש', 'לבנות את הקפסטון (מודול 15) בחשבון AWS אמיתי', 'לחזור על נושאים חלשים בתיעוד של AWS, לפי משקל התחומים', 'לעשות סטים של תרגול עם שעון: בערך 2.4 דקות לשאלה', 'לקבוע את המבחן, ולבדוק שוב את What\'s New בשבוע שלפני'] },
          explain: { en: 'Scope first, then knowledge, then hands-on, then gaps, then exam technique. 180 minutes for 75 questions is 2.4 minutes each, and the scenarios are long, so reading speed is part of the skill.', he: 'קודם ההיקף, אחר כך ידע, אחר כך עבודה מעשית, אחר כך פערים, ואז טכניקת מבחן. 180 דקות ל-75 שאלות הן 2.4 דקות לשאלה, והתרחישים ארוכים, אז מהירות קריאה היא חלק מהמיומנות.' } },
        { t: 'note', kind: 'tip', en: 'How to read a certification scenario: find the **constraint words**. "Least operational overhead" → the most managed option. "Most cost-effective" → batch, Flex tier, caching, a smaller model. "Data must stay in the EU" → a geographic inference profile, not a global one. "Must not be bypassed by the model" → a deterministic control (IAM, Policy), not a prompt. Two answers usually work; only one fits the constraint.', he: 'איך קוראים תרחיש של הסמכה: מחפשים את **מילות האילוץ**. "Least operational overhead" ← האפשרות הכי מנוהלת. "Most cost-effective" ← batch, Flex tier, caching, מודל קטן יותר. "המידע חייב להישאר ב-EU" ← geographic inference profile, לא global. "אסור שהמודל יוכל לעקוף" ← בקרה דטרמיניסטית (IAM, Policy), לא פרומפט. בדרך כלל שתי תשובות עובדות; רק אחת מתאימה לאילוץ.' },
        { t: 'h', en: 'Staying current: AWS changes every month', he: 'להישאר מעודכן: AWS משתנה כל חודש' },
        { t: 'p', en: 'Everything in this course was checked in November 2026. Some of it will be out of date within months. That is normal in this field, and the skill is knowing **where to look**:', he: 'כל מה שבקורס הזה נבדק בנובמבר 2026. חלק ממנו יתיישן בתוך חודשים. זה נורמלי בתחום הזה, והמיומנות היא לדעת **איפה לחפש**:' },
        { t: 'table', head: { en: ['Source', 'What you learn there'], he: ['מקור', 'מה לומדים שם'] }, rows: {
          en: [['[[What\'s New]] feed', 'Every launch, new Region and status change, as short posts. Filter by Bedrock.'], ['"Document history" page of the Bedrock User Guide', 'Dated list of every documented change: new APIs, renamed features, new models.'], ['"Document history" (release notes) of the AgentCore Developer Guide', 'The same for AgentCore: this is where the CLI change and new components first appeared.'], ['Model cards and the model lifecycle page', 'For each model: IDs, limits, Active / Legacy / EOL dates. Models launched from 2026-09-07 show an "EOL no sooner than" date.'], ['AWS General Reference: maintenance, sunset and full-shutdown lists', 'Which services are closing, with dates.'], ['AWS News Blog weekly roundup', 'A human summary of the week, good for a 5-minute habit.']],
          he: [['הפיד [[What\'s New]]', 'כל השקה, Region חדש ושינוי סטטוס, כפוסטים קצרים. מסננים לפי Bedrock.'], ['דף "Document history" של ה-Bedrock User Guide', 'רשימה מתוארכת של כל שינוי מתועד: APIs חדשים, יכולות ששינו שם, מודלים חדשים.'], ['"Document history" (release notes) של ה-AgentCore Developer Guide', 'אותו דבר ל-AgentCore: שם הופיעו לראשונה שינוי ה-CLI והרכיבים החדשים.'], ['Model cards ודף ה-model lifecycle', 'לכל מודל: IDs, גבולות, תאריכי Active / Legacy / EOL. מודלים שהושקו מ-2026-09-07 מציגים תאריך "EOL no sooner than".'], ['AWS General Reference: רשימות maintenance, sunset ו-full shutdown', 'אילו שירותים נסגרים, עם תאריכים.'], ['הסיכום השבועי של AWS News Blog', 'סיכום אנושי של השבוע, טוב להרגל של 5 דקות.']] } },
        { t: 'match', prompt: { en: 'You need an answer fast. Where do you look first?', he: 'אתה צריך תשובה מהר. איפה מחפשים קודם?' }, pairs: [
          { a: { en: 'Is this model ID still alive, and until when?', he: 'האם ה-model ID הזה עדיין חי, ועד מתי?' }, b: { en: 'The model card (lifecycle line)', he: 'ה-model card (שורת ה-lifecycle)' } },
          { a: { en: 'Is this service closed to new customers?', he: 'האם השירות הזה סגור ללקוחות חדשים?' }, b: { en: 'The maintenance / sunset lists in the AWS General Reference', he: 'רשימות maintenance / sunset ב-AWS General Reference' } },
          { a: { en: 'When did this API parameter appear?', he: 'מתי הפרמטר הזה ב-API הופיע?' }, b: { en: 'The Document history page of the user guide', he: 'דף Document history של ה-user guide' } },
          { a: { en: 'What launched this week?', he: 'מה הושק השבוע?' }, b: { en: 'What\'s New and the weekly roundup', he: 'What\'s New והסיכום השבועי' } },
          { a: { en: 'Which topics does the exam cover?', he: 'אילו נושאים המבחן מכסה?' }, b: { en: 'The official exam guide', he: 'מדריך המבחן הרשמי' } }
        ] },
        { t: 'quiz', q: { en: 'A practice question for AIP-C01 offers "Amazon Kendra" as the correct search service, but you know Kendra is in maintenance. How should you treat this on the real exam?', he: 'שאלת תרגול ל-AIP-C01 מציעה "Amazon Kendra" כשירות החיפוש הנכון, אבל אתה יודע ש-Kendra ב-maintenance. איך להתייחס לזה במבחן האמיתי?' },
          options: { en: ['Never choose a service that is in maintenance', 'Report the question and skip it', 'Assume the exam is wrong and pick a random answer', 'Answer by what the service does: the in-scope list still includes Kendra, so judge the option on fit to the scenario'], he: ['לעולם לא לבחור שירות שנמצא ב-maintenance', 'לדווח על השאלה ולדלג עליה', 'להניח שהמבחן טועה ולבחור תשובה אקראית', 'לענות לפי מה שהשירות עושה: הרשימה הרשמית עדיין כוללת את Kendra, אז שופטים את האפשרות לפי ההתאמה לתרחיש'] },
          answer: 3, explain: { en: 'Exams are updated more slowly than products. The official AIP-C01 list still names Kendra, Q Business, Q Developer and several SageMaker features. Choose by capability and by the constraint in the scenario. In a design meeting at work, you would of course propose the current replacement.', he: 'מבחנים מתעדכנים לאט יותר ממוצרים. הרשימה הרשמית של AIP-C01 עדיין כוללת את Kendra, Q Business, Q Developer וכמה יכולות של SageMaker. בוחרים לפי יכולת ולפי האילוץ בתרחיש. בישיבת תכנון בעבודה, כמובן שהיית מציע את המחליף העדכני.' } },
        { t: 'reveal', q: { en: 'Interview: "This field changes monthly. How do you make sure that what you build is not based on something AWS is about to retire?"', he: 'ראיון: "התחום הזה משתנה כל חודש. איך אתה מוודא שמה שאתה בונה לא מבוסס על משהו ש-AWS עומדת להוציא לפנסיה?"' },
          a: { en: 'Three habits. First, before I choose a service or a model I check its status: the lifecycle lists for services, the model card for models. Second, I keep model IDs, prompts and service choices in configuration, not spread through the code, and I keep an evaluation set, so that moving to a new model is a config change plus a test run and not a rewrite. Third, I read What\'s New or the weekly roundup once a week and the document history of the two or three services we depend on once a month. I also set a calendar reminder for every announced date that touches us, such as an EOL date of a model we use.', he: 'שלושה הרגלים. ראשית, לפני שאני בוחר שירות או מודל אני בודק את הסטטוס שלו: רשימות מחזור-החיים לשירותים, ה-model card למודלים. שנית, אני שומר model IDs, פרומפטים ובחירות שירות בקונפיגורציה ולא מפוזרים בקוד, ומחזיק סט evaluation, כך שמעבר למודל חדש הוא שינוי קונפיגורציה ועוד ריצת בדיקה ולא כתיבה מחדש. שלישית, אני קורא את What\'s New או את הסיכום השבועי פעם בשבוע, ואת ה-document history של שניים-שלושה שירותים שאנחנו תלויים בהם פעם בחודש. אני גם שם תזכורת ביומן לכל תאריך שהוכרז ונוגע לנו, כמו תאריך EOL של מודל שאנחנו משתמשים בו.' } }
      ]
    },
    {
      id: 'm14l6', minutes: 10,
      title: { en: 'Jargon and scenarios workout: which service?', he: 'אימון ז׳רגון ותרחישים: איזה שירות?' },
      blocks: [
        { t: 'p', en: 'You now have the whole map. In a design meeting somebody describes a need in one sentence and looks at you. This lesson trains that reflex.', he: 'עכשיו יש לך את כל המפה. בישיבת תכנון מישהו מתאר צורך במשפט אחד ומסתכל עליך. השיעור הזה מאמן את הרפלקס הזה.' },
        { t: 'match', prompt: { en: 'Match the word to its meaning.', he: 'התאם את המילה למשמעות שלה.' }, pairs: [
          { a: 'Maintenance', b: { en: 'Closed to new customers, existing ones keep working', he: 'סגור ללקוחות חדשים, הקיימים ממשיכים לעבוד' } },
          { a: 'Sunset', b: { en: 'An end-of-support date has been announced', he: 'הוכרז תאריך סיום תמיכה' } },
          { a: 'Blueprint', b: { en: 'A schema of fields to extract in BDA', he: 'סכמה של שדות לחילוץ ב-BDA' } },
          { a: 'Spec', b: { en: 'Requirements → design → tasks, before code', he: 'דרישות ← תכנון ← משימות, לפני קוד' } },
          { a: 'Endpoint', b: { en: 'A hosted model on compute you pay for', he: 'מודל מתארח על מחשוב שאתה משלם עליו' } },
          { a: 'Vector bucket', b: { en: 'The S3 Vectors container for vector indexes', he: 'המכל של S3 Vectors ל-vector indexes' } }
        ] },
        { t: 'match', prompt: { en: 'Which service? Match the one-sentence need to the best first answer.', he: 'איזה שירות? התאם את הצורך במשפט אחד לתשובה הראשונה הכי טובה.' }, pairs: [
          { a: { en: '"We want to host a model we trained ourselves."', he: '"אנחנו רוצים לארח מודל שאימנו בעצמנו."' }, b: 'SageMaker AI' },
          { a: { en: '"Our employees want an AI workspace over company data, no coding."', he: '"העובדים שלנו רוצים סביבת AI על המידע של החברה, בלי קוד."' }, b: 'AWS Quick' },
          { a: { en: '"Our developers want an agentic IDE."', he: '"המפתחים שלנו רוצים IDE אגנטי."' }, b: 'Kiro' },
          { a: { en: '"We need answers from our documents inside our own app."', he: '"אנחנו צריכים תשובות מהמסמכים שלנו בתוך האפליקציה שלנו."' }, b: { en: 'Bedrock Managed Knowledge Base', he: 'Bedrock Managed Knowledge Base' } },
          { a: { en: '"We must move a 15-year-old .NET system forward."', he: '"אנחנו חייבים לקדם מערכת .NET בת 15 שנה."' }, b: 'AWS Transform' },
          { a: { en: '"We need an agent with tools, memory and auth in production."', he: '"אנחנו צריכים סוכן עם כלים, זיכרון ו-auth בפרודקשן."' }, b: 'Bedrock AgentCore' }
        ] },
        { t: 'quiz', q: { en: 'A media company has 80,000 hours of video. They want to search "the scene where the mayor cuts the ribbon" and jump to that moment. Which building block is the core of the search?', he: 'לחברת מדיה יש 80,000 שעות וידאו. הם רוצים לחפש "הסצנה שבה ראש העיר גוזר את הסרט" ולקפוץ לרגע הזה. איזו אבן בניין היא הליבה של החיפוש?' },
          options: { en: ['A multimodal embeddings model (such as Nova Multimodal Embeddings) plus a vector store', 'Amazon Polly', 'Titan Text Embeddings V2 on the file names', 'Amazon Lex with one intent per scene'], he: ['מודל multimodal embeddings (כמו Nova Multimodal Embeddings) ועוד vector store', 'Amazon Polly', 'Titan Text Embeddings V2 על שמות הקבצים', 'Amazon Lex עם intent אחד לכל סצנה'] },
          answer: 0, explain: { en: 'Searching video by meaning needs embeddings of the video itself, stored in a vector store; Nova Multimodal Embeddings embeds text, image, document, video and audio into one space. Text embeddings of file names know nothing about what happens inside the video. A second valid route for speech-heavy video is to turn speech into text first (BDA or Transcribe) and search the text.', he: 'חיפוש וידאו לפי משמעות דורש embeddings של הוידאו עצמו, שמורים ב-vector store; Nova Multimodal Embeddings עושה embedding לטקסט, תמונה, מסמך, וידאו ואודיו לאותו מרחב. Text embeddings של שמות קבצים לא יודעים כלום על מה שקורה בתוך הוידאו. מסלול תקף נוסף לוידאו עם הרבה דיבור הוא להפוך קודם דיבור לטקסט (BDA או Transcribe) ולחפש בטקסט.' } },
        { t: 'quiz', q: { en: 'Your team still runs a production agent on Bedrock Agents Classic. It works. A teammate wants to "migrate tonight because it is deprecated". What is the accurate picture?', he: 'הצוות שלך עדיין מריץ סוכן פרודקשן על Bedrock Agents Classic. הוא עובד. חבר צוות רוצה "לעשות מיגרציה הלילה כי זה deprecated". מה התמונה המדויקת?' },
          options: { en: ['It will stop working on 2027-04-30', 'It is in maintenance: no new features, no end-of-life date and no migration deadline. Plan a calm migration to AgentCore and build new agents there.', 'It was shut down on 2026-07-30', 'It was renamed AgentCore Harness and nothing needs to change'], he: ['הוא יפסיק לעבוד ב-2027-04-30', 'הוא ב-maintenance: אין יכולות חדשות, אין תאריך end-of-life ואין דדליין למיגרציה. מתכננים מיגרציה רגועה ל-AgentCore ובונים שם סוכנים חדשים.', 'הוא נסגר ב-2026-07-30', 'השם שלו שונה ל-AgentCore Harness ולא צריך לשנות כלום'] },
          answer: 1, explain: { en: 'Maintenance is not sunset. Existing Agents Classic users keep everything; the model catalog is frozen and there are no new features, which is the real reason to move. 2027-04-30 is the Q Developer date. 2026-07-30 is when Classic closed to **new** customers. The harness is the closest AgentCore equivalent, but it is a different service that you migrate to.', he: 'Maintenance זה לא sunset. משתמשים קיימים של Agents Classic שומרים הכול; קטלוג המודלים קפוא ואין יכולות חדשות, וזו הסיבה האמיתית לעבור. 2027-04-30 הוא התאריך של Q Developer. 2026-07-30 הוא התאריך שבו Classic נסגר ללקוחות **חדשים**. ה-harness הוא המקביל הקרוב ביותר ב-AgentCore, אבל זה שירות אחר שעוברים אליו.' } },
        { t: 'quiz', q: { en: 'A hospital wants to pull 20 fixed fields from discharge letters (PDF scans), route low-confidence results to a nurse, and later ask free questions over the same letters. Which combination is the most sensible?', he: 'בית חולים רוצה לחלץ 20 שדות קבועים ממכתבי שחרור (סריקות PDF), להעביר תוצאות עם ביטחון נמוך לאחות, ואחר כך לשאול שאלות חופשיות על אותם מכתבים. איזה שילוב הכי הגיוני?' },
          options: { en: ['Amazon Polly for the fields, Amazon Lex for the questions', 'One chat model for everything, no storage', 'Bedrock Data Automation with a blueprint for the fields, and a Knowledge Base for the questions', 'SageMaker AI training job for the fields, Amazon Translate for the questions'], he: ['Amazon Polly לשדות, Amazon Lex לשאלות', 'מודל צ׳אט אחד להכול, בלי אחסון', 'Bedrock Data Automation עם blueprint לשדות, ו-Knowledge Base לשאלות', 'SageMaker AI training job לשדות, Amazon Translate לשאלות'] },
          answer: 2, explain: { en: 'Two different jobs. Fixed fields with confidence scores = extraction, which is BDA with a blueprint. Free questions over many documents = retrieval, which is a Knowledge Base (and BDA can even be its parser). One chat model with no storage cannot search thousands of letters and gives no confidence score.', he: 'שתי משימות שונות. שדות קבועים עם confidence scores = חילוץ, כלומר BDA עם blueprint. שאלות חופשיות על הרבה מסמכים = אחזור, כלומר Knowledge Base (ו-BDA אפילו יכול להיות ה-parser שלו). מודל צ׳אט אחד בלי אחסון לא יכול לחפש באלפי מכתבים ולא נותן confidence score.' } },
        { t: 'quiz', q: { en: 'A team must generate product images in a new Bedrock project. A two-year-old tutorial uses Nova Canvas. What should they do?', he: 'צוות צריך לייצר תמונות מוצר בפרויקט Bedrock חדש. טוטוריאל בן שנתיים משתמש ב-Nova Canvas. מה עליהם לעשות?' },
          options: { en: ['Follow the tutorial; Amazon models are never retired', 'Use Titan Image Generator instead', 'Use Nova Micro with a detailed prompt', 'Check the model cards: Nova Canvas is EOL since 2026-09-30, so pick an image model that is Active in the catalog (for example from Stability AI)'], he: ['ללכת לפי הטוטוריאל; מודלים של Amazon אף פעם לא יוצאים לפנסיה', 'להשתמש ב-Titan Image Generator במקום', 'להשתמש ב-Nova Micro עם פרומפט מפורט', 'לבדוק את ה-model cards: Nova Canvas ב-EOL מאז 2026-09-30, אז בוחרים מודל תמונות שהוא Active בקטלוג (לדוגמה של Stability AI)'] },
          answer: 3, explain: { en: 'After EOL, calls to Nova Canvas fail with ResourceNotFoundException. Titan Image Generator is also no longer in the model list, and Nova Micro is text only. The habit matters more than the answer: status first, then code.', he: 'אחרי EOL, קריאות ל-Nova Canvas נכשלות עם ResourceNotFoundException. גם Titan Image Generator כבר לא ברשימת המודלים, ו-Nova Micro הוא טקסט בלבד. ההרגל חשוב יותר מהתשובה: קודם סטטוס, אחר כך קוד.' } },
        { t: 'reveal', q: { en: 'Explain in under a minute, to a new teammate, the difference between Bedrock, AgentCore, SageMaker AI and AWS Quick.', he: 'הסבר בפחות מדקה, לחבר צוות חדש, את ההבדל בין Bedrock, AgentCore, SageMaker AI ו-AWS Quick.' },
          a: { en: 'Bedrock is where you **call models**: one API to many foundation models, plus knowledge bases, guardrails and evaluations around them. AgentCore is where you **run agents** built on those models: runtime, memory, gateway to tools, identity, policy, observability. SageMaker AI is where you **build and host your own models**: training jobs, endpoints, the ML lifecycle. AWS Quick is a **finished product for business users**: chat, research, automation and dashboards over company data, no code. Developers building a product live in the first two, ML engineers in the third, and everyone else uses the fourth.', he: 'Bedrock הוא המקום שבו **קוראים למודלים**: API אחד להרבה foundation models, ועוד knowledge bases, guardrails ו-evaluations סביבם. AgentCore הוא המקום שבו **מריצים סוכנים** שבנויים על המודלים האלה: runtime, memory, gateway לכלים, identity, policy, observability. SageMaker AI הוא המקום שבו **בונים ומארחים מודלים משלך**: training jobs, endpoints, מחזור החיים של ML. AWS Quick הוא **מוצר מוגמר למשתמשים עסקיים**: צ׳אט, מחקר, אוטומציה ודשבורדים על מידע החברה, בלי קוד. מפתחים שבונים מוצר חיים בשני הראשונים, ML engineers בשלישי, וכל השאר משתמשים ברביעי.' } },
        { t: 'reveal', q: { en: 'A manager asks: "Should our whole team get certified?" Give a balanced answer.', he: 'מנהל שואל: "כדאי שכל הצוות יעבור הסמכה?" תן תשובה מאוזנת.' },
          a: { en: 'It depends on the role. For non-developers who work with us (product, sales, support leads), AI Practitioner gives a shared vocabulary cheaply. For developers who build GenAI features, the Generative AI Developer - Professional exam is worth it because its guide forces you to cover the areas people skip: security, cost, testing. For ML engineers, the new ML Engineer - Associate version. But the certificate is the by-product. The real value is the structured study and the hands-on project, so I would pair the exam with building one real thing, such as the capstone in the next module.', he: 'תלוי בתפקיד. למי שלא מפתח ועובד איתנו (מוצר, מכירות, ראשי תמיכה), AI Practitioner נותן אוצר מילים משותף בזול. למפתחים שבונים יכולות GenAI, מבחן Generative AI Developer - Professional שווה את זה כי המדריך שלו מכריח לכסות את התחומים שמדלגים עליהם: אבטחה, עלות, בדיקות. ל-ML engineers, הגרסה החדשה של ML Engineer - Associate. אבל התעודה היא תוצר לוואי. הערך האמיתי הוא הלימוד המסודר והפרויקט המעשי, אז הייתי מצמיד למבחן בנייה של דבר אמיתי אחד, כמו הקפסטון במודול הבא.' } },
        { t: 'task', title: { en: 'After landing: 30 minutes that keep you current', he: 'אחרי הנחיתה: 30 דקות ששומרות אותך מעודכן' }, steps: {
          en: ['Open the AWS What\'s New page and filter by Amazon Bedrock. Read the titles of the last 30 days and list what changed since November 2026.', 'Open the Bedrock User Guide "Document history" page and the AgentCore Developer Guide release notes. Bookmark both.', 'Open the model card of the model you plan to use. Write down its lifecycle status and its "EOL no sooner than" date if it has one.', 'Open the AWS General Reference lifecycle pages (maintenance, sunset, full shutdown) and check whether any service from this module moved.', 'Download the official AIP-C01 exam guide. Mark each task statement green, yellow or red by how well you know it.', 'Try PartyRock for ten minutes: build a tiny app and show it to someone non-technical.', 'If you ever created a SageMaker AI endpoint for a test, delete it now. Endpoints bill while idle.'],
          he: ['פתח את דף What\'s New של AWS וסנן לפי Amazon Bedrock. קרא את הכותרות של 30 הימים האחרונים ורשום מה השתנה מאז נובמבר 2026.', 'פתח את דף "Document history" של ה-Bedrock User Guide ואת ה-release notes של ה-AgentCore Developer Guide. שמור את שניהם בסימניות.', 'פתח את ה-model card של המודל שאתה מתכנן להשתמש בו. רשום את סטטוס ה-lifecycle שלו ואת תאריך ה-"EOL no sooner than" אם יש לו.', 'פתח את דפי מחזור-החיים ב-AWS General Reference (maintenance, sunset, full shutdown) ובדוק אם שירות כלשהו מהמודול הזה זז.', 'הורד את מדריך המבחן הרשמי של AIP-C01. סמן כל task statement בירוק, צהוב או אדום לפי כמה טוב אתה מכיר אותו.', 'נסה את PartyRock לעשר דקות: בנה אפליקציה קטנטנה והראה אותה למישהו לא טכני.', 'אם יצרת פעם endpoint של SageMaker AI לבדיקה, מחק אותו עכשיו. Endpoints מחייבים גם במנוחה.'] } }
      ]
    }
  ]
});
